INSERT INTO `dataset` VALUES ('FreedomIntelligence/medical-o1-reasoning-SFT','fc2c9e8a37b38f38da6d449564a8c350b244aef4','finetuning','[\"GPT-4o-guided search for correct CoT trajectories (Backtracking, Exploring New Paths, Verification, Correction)\", \"GPT-4o verifier validation of final answers\"]','apache-2.0',366,'{\"uri\": \"https://huggingface.co/datasets/FreedomIntelligence/medical-o1-reasoning-SFT\", \"name\": \"Medical-o1 Reasoning SFT\", \"size\": \"20K SFT examples (English)\", \"hf_id\": \"FreedomIntelligence/medical-o1-reasoning-SFT\", \"modality\": \"text\", \"provider\": \"FreedomIntelligence\", \"description\": \"20K SFT examples of (question, complex chain-of-thought, formal response) synthesized with GPT-4o by searching for correct reasoning trajectories over the verifiable medical problems, validated via the GPT-4o verifier. Note: the currently distributed HF dataset revision has been split (2025-04-22) to keep only the medical-only SFT file plus a medical+general mix file; the English medical-only file corresponds to the ~20K examples described in the paper.\", \"hf_last_modified\": \"2025-04-22\"}'),('FreedomIntelligence/medical-o1-verifiable-problem','46d5175eb74fdef3516d51d52e8c40db04bbdf35','finetuning','[\"difficulty filtering via 3 small LLMs (Gemma2-9B, Llama-3.1-8B, Qwen2.5-7B)\", \"removal of \'incorrect option\' / multiple-correct-answer questions\", \"GPT-4o ambiguity filtering\", \"GPT-4o reformatting from multiple-choice to open-ended question + ground-truth answer\", \"decontamination screening against evaluation benchmarks\"]','apache-2.0',365,'{\"uri\": \"https://huggingface.co/datasets/FreedomIntelligence/medical-o1-verifiable-problem\", \"name\": \"Medical-o1 Verifiable Problem\", \"size\": \"40K verifiable medical problems (from a 192K multiple-choice source pool)\", \"hf_id\": \"FreedomIntelligence/medical-o1-verifiable-problem\", \"modality\": \"text\", \"provider\": \"FreedomIntelligence\", \"description\": \"40K open-ended medical problems with unique ground-truth answers, converted from a pool of 192K MedQA-USMLE/MedMCQA multiple-choice training questions. 20K used for SFT (stage 1) and 20K reserved for RL (stage 2); paper also mentions 4K unconverted closed-set questions and 5K general (non-medical) verification questions from MMLU-Pro added for domain-compatibility experiments (not part of the released HF dataset).\", \"hf_last_modified\": \"2024-12-30\"}'),('GBaker/MedQA-USMLE-4-options','0fb93dd23a7339b6dcd27e241cb9b5eca62d4d18','finetuning,evaluation','[\"difficulty filtering (removed questions 3 small LLMs all answered correctly)\", \"removal of short/unambiguous questions\"]','cc-by-4.0',363,'{\"uri\": \"https://huggingface.co/datasets/GBaker/MedQA-USMLE-4-options\", \"name\": \"MedQA-USMLE (training set)\", \"hf_id\": \"GBaker/MedQA-USMLE-4-options\", \"modality\": \"text\", \"provider\": \"Original MedQA authors (Jin et al.); training set reused by FreedomIntelligence\", \"description\": \"USMLE-style multiple-choice medical exam questions; its training split was one of the two source pools of closed-set questions transformed into HuatuoGPT-o1\'s verifiable medical problems.\", \"hf_last_modified\": \"2023-01-24\"}'),('HPAI-BSC/Egida','config \'Egida\' (splits: full/train/test), commit fe1ad52','evaluation','[\"manual curation and review from 9 public source datasets\", \"MinHash deduplication\", \"manual multi-label topic classification (27 topics)\", \"18 jailbreak-attack augmentations applied to each seed prompt\", \"topic/attack-style-disjoint train/test split to avoid contamination\"]','apache-2.0',373,'{\"uri\": \"https://huggingface.co/datasets/HPAI-BSC/Egida\", \"name\": \"Egida\", \"size\": \"61,830 total instances (config \'Egida\', split \'full\'); train split 22,390 rows; test split 10,940 rows; splits are constructed with non-overlapping topics and attack styles\", \"hf_id\": \"HPAI-BSC/Egida\", \"modality\": \"text\", \"provider\": \"HPAI-BSC\", \"description\": \"Collection of 2,949 manually curated unsafe/jailbreak-eliciting requests gathered from nine public sources, deduplicated via MinHash, manually multi-labeled across 27 fine-grained safety topics, and expanded with 18 distinct jailbreaking attack techniques (incl. DAN, DeepInception, ReNeLLM, and Qwen-72B-Chat-generated past-tense/technical-report styles).\", \"hf_last_modified\": \"2025-08-22\"}'),('HiTZ/truthful_judge','cb0bbf9dfa62ba1eda8fdad44a557e24e072426c','finetuning,evaluation','[\"professional translation of English TruthfulQA questions\", \"creation of new culturally-specific questions per target language\", \"validation and refinement of questions/answers\", \"pairing of one correct and one incorrect answer per instance\", \"conversion to Yes/No judge prompt-completion format\"]','Apache-2.0',370,'{\"uri\": \"https://huggingface.co/datasets/HiTZ/truthful_judge\", \"name\": \"TruthfulQA-Multi Judge Training Data (Truthfulness)\", \"size\": \"817 source TruthfulQA questions across 38 categories per language (per paper), expanded into judge prompt/completion pairs; exact instance count not stated in card\", \"hf_id\": \"HiTZ/truthful_judge\", \"modality\": \"text\", \"provider\": \"HiTZ Center - Ixa, University of the Basque Country (UPV/EHU) and collaborators\", \"description\": \"Prompt/completion pairs (Yes/No) for training LLM-as-a-Judge truthfulness models; derived from TruthfulQA (Lin et al., 2022) with professional translation plus new culturally-specific questions for Basque, Catalan, Galician and Spanish. Two configs: \'en\' (finetune_truth.jsonl, English only) and \'multi\' (finetune_truth_multi.json, all 5 languages) - this model was trained on the multilingual (\'multi\'/MT) configuration.\", \"hf_last_modified\": \"2025-05-22\"}'),('Idavidrein/gpqa','83022cefff930aea54f654c0b282e74b9eeda5c6','evaluation',NULL,'cc-by-4.0',369,'{\"uri\": \"https://huggingface.co/datasets/Idavidrein/gpqa\", \"name\": \"GPQA (Genetics track)\", \"hf_id\": \"Idavidrein/gpqa\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Graduate-level Google-proof Q&A science benchmark.\", \"hf_last_modified\": \"2026-09-21\"}'),('NousResearch/hermes-function-calling-v1','dae3e1d28cfbcf4b915c04ea1e072030529b4bda','finetuning',NULL,'apache-2.0',402,'{\"uri\": \"https://huggingface.co/datasets/NousResearch/hermes-function-calling-v1\", \"name\": \"Hermes Function Calling training set v1\", \"hf_id\": \"NousResearch/hermes-function-calling-v1\", \"modality\": \"text\", \"provider\": \"Nous Research\", \"description\": \"Existing Nous Research dataset used as one of the curated sources contributing to the General Instructions / tool-use portion of the Hermes 3 SFT mixture.\", \"hf_last_modified\": \"2026-01-03\"}'),('Rowan/hellaswag','218ec52e09a7e7462a5400043bb9a69a41d06b76','evaluation',NULL,NULL,404,'{\"uri\": \"https://huggingface.co/datasets/Rowan/hellaswag\", \"name\": \"HellaSwag\", \"size\": \"10,042 validation examples (39,905 train, 10,003 test with hidden labels)\", \"hf_id\": \"Rowan/hellaswag\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Commonsense sentence-completion benchmark.\", \"hf_last_modified\": \"2025-07-10\"}'),('TIGER-Lab/MMLU-Pro','b189ec765aa7ed75c8acfea42df31fdae71f97be','evaluation',NULL,'mit',368,'{\"uri\": \"https://huggingface.co/datasets/TIGER-Lab/MMLU-Pro\", \"name\": \"MMLU-Pro (Health track)\", \"hf_id\": \"TIGER-Lab/MMLU-Pro\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Harder, 10-option version of MMLU with more reasoning-focused questions.\", \"hf_last_modified\": \"2026-05-02\"}'),('allenai/ai2_arc','210d026faf9955653af8916fad021475a3f00453','evaluation',NULL,'cc-by-sa-4.0',381,'{\"uri\": \"https://huggingface.co/datasets/allenai/ai2_arc\", \"name\": \"ARC-Challenge\", \"hf_id\": \"allenai/ai2_arc\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"AI2 Reasoning Challenge, grade-school science questions (Challenge split).\", \"hf_last_modified\": \"2023-12-21\"}'),('allenai/winogrande','01e74176c63542e6b0bcb004dcdea22d94fb67b5','evaluation',NULL,'Apache-2.0',394,'{\"uri\": \"https://huggingface.co/datasets/allenai/winogrande\", \"name\": \"Winogrande\", \"size\": \"1,267 validation examples (winogrande_xl: 40,398 train, 1,767 test with hidden labels)\", \"hf_id\": \"allenai/winogrande\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Large-scale Winograd-schema commonsense reasoning benchmark.\", \"hf_last_modified\": \"2025-07-11\"}'),('cais/mmlu','c30699e8356da336a370243923dbaf21066bb9fe','evaluation',NULL,'mit',376,'{\"uri\": \"https://huggingface.co/datasets/cais/mmlu\", \"name\": \"MMLU\", \"hf_id\": \"cais/mmlu\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Massive Multitask Language Understanding: 57-subject multiple-choice knowledge benchmark.\", \"hf_last_modified\": \"2024-03-08\"}'),('google-research-datasets/mbpp','4bb6404fdc6cacfda99d4ac4205087b89d32030c','evaluation',NULL,'cc-by-4.0',383,'{\"uri\": \"https://huggingface.co/datasets/google-research-datasets/mbpp\", \"name\": \"MBPP++ base\", \"hf_id\": \"google-research-datasets/mbpp\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Mostly Basic Python Problems code generation benchmark.\", \"hf_last_modified\": \"2024-01-04\"}'),('google/IFEval','966cd89545d6b6acfd7638bc708b98261ca58e84','evaluation',NULL,'apache-2.0',380,'{\"uri\": \"https://huggingface.co/datasets/google/IFEval\", \"name\": \"IFEval\", \"hf_id\": \"google/IFEval\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Instruction-following evaluation with verifiable formatting constraints.\", \"hf_last_modified\": \"2024-08-14\"}'),('hendrycks/competition_math','71b758ecc688b2822d07ffa7f8393299f1dc7cac','evaluation',NULL,'mit',386,'{\"uri\": \"https://huggingface.co/datasets/hendrycks/competition_math\", \"name\": \"MATH (CoT)\", \"hf_id\": \"hendrycks/competition_math\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Competition mathematics problem benchmark.\", \"hf_last_modified\": \"2023-06-08\"}'),('lukaemon/bbh','982bb89fd79532a8ac676a61fc42eb1aeec63f99','evaluation',NULL,'MIT',395,'{\"uri\": \"https://huggingface.co/datasets/lukaemon/bbh\", \"name\": \"BIG-Bench Hard\", \"size\": \"27 task configs, 250 test examples each for most tasks (6,511 examples total)\", \"hf_id\": \"lukaemon/bbh\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"BIG-Bench Hard, 23 challenging reasoning tasks.\", \"hf_last_modified\": \"2025-07-11\"}'),('openai/gsm8k','740312add88f781978c0658806c59bc2815b9866','evaluation',NULL,'mit',385,'{\"uri\": \"https://huggingface.co/datasets/openai/gsm8k\", \"name\": \"GSM8K (CoT)\", \"hf_id\": \"openai/gsm8k\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Grade-school math word problems benchmark.\", \"hf_last_modified\": \"2026-03-23\"}'),('openai/openai_humaneval','7dce6050a7d6d172f3cc5c32aa97f52fa1a2e544','evaluation',NULL,'mit',382,'{\"uri\": \"https://huggingface.co/datasets/openai/openai_humaneval\", \"name\": \"HumanEval\", \"hf_id\": \"openai/openai_humaneval\", \"modality\": \"text\", \"provider\": \"third-party academic benchmark authors\", \"description\": \"Hand-written Python programming problems with unit tests.\", \"hf_last_modified\": \"2024-01-04\"}'),('openlifescienceai/medmcqa','91c6572c454088bf71b679ad90aa8dffcd0d5868','finetuning,evaluation','[\"difficulty filtering (removed questions 3 small LLMs all answered correctly)\", \"removal of short/unambiguous questions\"]','apache-2.0',364,'{\"uri\": \"https://huggingface.co/datasets/openlifescienceai/medmcqa\", \"name\": \"MedMCQA (training set)\", \"hf_id\": \"openlifescienceai/medmcqa\", \"modality\": \"text\", \"provider\": \"Original MedMCQA authors; training set reused by FreedomIntelligence\", \"description\": \"Indian medical entrance exam multiple-choice questions; its training split was the second source pool of closed-set questions transformed into HuatuoGPT-o1\'s verifiable medical problems.\", \"hf_last_modified\": \"2024-01-04\"}'),('qiaojin/PubMedQA','9001f2853fb87cab8d220904e0de81ac6973b318','evaluation',NULL,'mit',367,'{\"name\": \"PubMedQA\", \"hf_id\": \"qiaojin/PubMedQA\", \"hf_last_modified\": \"2024-03-06\"}'),('slug:agieval-english','8670dcc6a5aa2c5e177b14905ec892df983446cd','evaluation',NULL,'MIT',392,'{\"uri\": \"https://huggingface.co/datasets/lighteval/agi_eval_en\", \"name\": \"AGIEval English\", \"size\": \"9 English-language exam subtasks (task sizes range from ~230 to ~1,000 examples each)\", \"hf_id\": \"lighteval/agi_eval_en\", \"provider\": \"Ruixiang Cui et al. (Microsoft Research / Westlake University)\", \"description\": \"The English-language subtasks (e.g. AQuA-RAT, LogiQA-EN, LSAT-AR/LR/RC, SAT-EN, SAT-Math) of AGIEval, a human-centric benchmark built from real-world standardized admission and qualification exams.\", \"hf_last_modified\": \"2025-12-18\"}'),('slug:api-bank','12e8158b7628c168f07e8f31fbbe3445e99f44cf','evaluation',NULL,'MIT',387,'{\"uri\": \"https://huggingface.co/datasets/liminghao1630/API-Bank\", \"name\": \"API-Bank\", \"size\": \"~95 MB (train/test splits across level 1-3 API and response files)\", \"hf_id\": \"liminghao1630/API-Bank\", \"provider\": \"Alibaba (API-Bank paper authors)\", \"description\": \"A benchmark of dialog traces with tool-call annotations across three complexity levels for evaluating LLM tool-use / API-calling ability.\", \"hf_last_modified\": \"2023-11-17\"}'),('slug:bfcl','61fc0608cfd831fcfbbaa676ebdfef0ed963eeda','evaluation',NULL,'Apache-2.0',388,'{\"uri\": \"https://huggingface.co/datasets/gorilla-llm/Berkeley-Function-Calling-Leaderboard\", \"name\": \"BFCL\", \"size\": \"27 dataset files spanning simple/parallel/multi-turn/live function-calling categories\", \"hf_id\": \"gorilla-llm/Berkeley-Function-Calling-Leaderboard\", \"provider\": \"UC Berkeley Gorilla LLM project (Sky Computing Lab)\", \"description\": \"A live leaderboard/benchmark dataset evaluating LLMs\' ability to call functions/tools across simple, parallel, multiple, multi-turn and multi-language (Java, JavaScript, REST, SQL) scenarios.\", \"hf_last_modified\": \"2026-04-29\"}'),('slug:boolq','35b264d03638db9f4ce671b711558bf7ff0f80d5','evaluation',NULL,'CC BY-SA 3.0',399,'{\"uri\": \"https://huggingface.co/datasets/google/boolq\", \"name\": \"BoolQ\", \"size\": \"3,270 validation examples (9,427 train)\", \"hf_id\": \"google/boolq\", \"provider\": \"Google Research\", \"description\": \"A question-answering dataset of naturally occurring yes/no questions paired with a supporting passage, used to study surprisingly hard inference over unconstrained real-world questions.\", \"hf_last_modified\": \"2024-01-22\"}'),('slug:cleaned-alpaca','12567cabf869d7c92e573c7c783905fc160e9639',NULL,NULL,'CC-BY-4.0',362,'{\"uri\": \"https://github.com/gururise/AlpacaDataCleaned\", \"name\": \"Cleaned Alpaca Dataset\", \"size\": \"~51,760 instruction-input-output examples (10K-100K range per dataset card)\", \"hf_id\": \"yahma/alpaca-cleaned\", \"modality\": \"text\", \"provider\": \"Gene Ruebsamen (community)\", \"description\": \"Deduplicated / quality-cleaned version of the original Stanford Alpaca instruction-tuning dataset, used as the base instruction pool for constructing synthetic_alpaca.\", \"hf_last_modified\": \"2023-04-10\"}'),('slug:commonsenseqa','94630fe30dad47192a8546eb75f094926d47e155','evaluation',NULL,'MIT',393,'{\"uri\": \"https://huggingface.co/datasets/tau/commonsense_qa\", \"name\": \"CommonSenseQA\", \"size\": \"1,221 validation examples (9,741 train, 1,140 test with hidden labels)\", \"hf_id\": \"tau/commonsense_qa\", \"provider\": \"Tel Aviv University / Allen Institute for AI\", \"description\": \"A multiple-choice commonsense question answering dataset built from ConceptNet, where each question has one correct answer and four distractors requiring commonsense knowledge to resolve.\", \"hf_last_modified\": \"2024-01-04\"}'),('slug:drop','95cda593fae71b60b5b19f82de3fcf3298c1239c','evaluation',NULL,'CC BY-SA 4.0',400,'{\"uri\": \"https://huggingface.co/datasets/ucinlp/drop\", \"name\": \"DROP\", \"size\": \"9,535 validation examples (77,400 train)\", \"hf_id\": \"ucinlp/drop\", \"provider\": \"University of California, Irvine (UCI NLP)\", \"description\": \"A crowdsourced, adversarially-created reading comprehension benchmark of ~96k questions requiring discrete reasoning (addition, counting, sorting) over paragraphs.\", \"hf_last_modified\": \"2024-01-17\"}'),('slug:egida-dpo-qwen2.5-7b-instruct','config \'Egida-DPO-Qwen2.5-7B-Instruct\', split \'train\'','finetuning','[\"inference of Qwen2.5-7B-Instruct on Egida prompts to obtain candidate unsafe completions\", \"pairing of unsafe completions (\'rejected\') with Egida-S safe completions (\'chosen\')\"]','apache-2.0',375,'{\"uri\": \"https://huggingface.co/datasets/HPAI-BSC/Egida\", \"name\": \"Egida-DPO-Qwen2.5-7B-Instruct\", \"size\": \"6,410 preference pairs\", \"hf_id\": \"HPAI-BSC/Egida\", \"modality\": \"text\", \"provider\": \"HPAI-BSC\", \"description\": \"Model-specific DPO preference dataset built by running inference with Qwen2.5-7B-Instruct on Egida prompts: unsafe model generations are kept as \'rejected\' responses and paired with Egida-S safe responses as \'chosen\', for direct preference optimization targeting this specific model.\", \"hf_last_modified\": \"2025-08-22\"}'),('slug:egida-s','config \'Egida-S\', split \'train\'',NULL,'[\"safe-response generation via Mistral-7B-v0.3 and Phi-3-Small-8k\"]','apache-2.0',374,'{\"uri\": \"https://huggingface.co/datasets/HPAI-BSC/Egida\", \"name\": \"Egida-S\", \"size\": \"61,830 rows\", \"hf_id\": \"HPAI-BSC/Egida\", \"modality\": \"text\", \"provider\": \"HPAI-BSC\", \"description\": \"Egida unsafe prompts paired with safe reference responses generated by Mistral-7B-v0.3 and Phi-3-Small-8k, used as the \'chosen\' side of DPO preference pairs.\", \"hf_last_modified\": \"2025-08-22\"}'),('slug:gorilla-api-bench','ac21e1892e634dfa25f8ad75f16cbdbfb0a5736d','evaluation',NULL,'Apache-2.0',389,'{\"uri\": \"https://huggingface.co/datasets/gorilla-llm/APIBench\", \"name\": \"Gorilla Benchmark API Bench\", \"size\": \"1,600+ API entries across HuggingFace/TensorFlow/TorchHub frameworks\", \"hf_id\": \"gorilla-llm/APIBench\", \"provider\": \"UC Berkeley (Shishir G. Patil, Tianjun Zhang, Xin Wang, Joseph E. Gonzalez - Gorilla project)\", \"description\": \"Training/evaluation data of 1,600+ API calls (HuggingFace, TensorFlow Hub, TorchHub) used to benchmark LLMs invoking APIs accurately while minimizing hallucination.\", \"hf_last_modified\": \"2023-05-29\"}'),('slug:hermes-3-dpo-preference-data',NULL,'finetuning',NULL,NULL,403,'{\"name\": \"Hermes 3 DPO preference pairs\", \"modality\": \"text\", \"provider\": \"Nous Research\", \"description\": \"Chosen/rejected preference pairs used for the LoRA DPO alignment phase after SFT; exact composition and sourcing are not disclosed in the technical report.\"}'),('slug:hermes-3-sft-mixture',NULL,'finetuning','[\"token length thresholding\", \"removal of refusals and improperly formatted responses\", \"removal of conversations with missing/empty turns\", \"prioritization of conversations generated by the strongest models\", \"Evol-Instruct-style complexity augmentation for domain-specific data\", \"sample packing (flash-attention variable-length, ~96% efficiency)\"]',NULL,401,'{\"name\": \"Hermes 3 SFT dataset mixture\", \"size\": \"~390M tokens (270M output/response tokens, 120M input/instruction tokens)\", \"modality\": \"text\", \"provider\": \"Nous Research\", \"description\": \"Proprietary Nous Research instruction-tuning dataset spanning General Instructions, Domain Expert, Math, Roleplaying, Coding, Tool Use/Agentic/RAG, Content Generation, and Steering & Alignment categories; curated from existing sources plus Evol-Instruct-style synthetic generation, then filtered for length, refusals, empty turns, and generation quality.\"}'),('slug:llama-3.1-post-training-data',NULL,'finetuning','[\"human annotation\", \"rejection sampling\", \"synthetic data generation\", \"preference pair construction\", \"safety/borderline data curation\"]',NULL,379,'{\"name\": \"Llama 3.1 post-training data (SFT + preference data)\", \"modality\": \"text\", \"provider\": \"Meta\", \"description\": \"Multi-round instruction-tuning and alignment data combining human-annotated examples, rejection-sampled model responses, synthetic/model-generated data, and preference pairs used for DPO; also includes safety and borderline-case data.\"}'),('slug:llama-3.1-pretraining-mixture',NULL,'pretraining','[\"deduplication\", \"HTML extraction and cleaning\", \"quality filtering\", \"PII-heavy domain filtering\", \"unsafe/adult-domain filtering\", \"domain-specific code and math processing\", \"multilingual processing\"]',NULL,372,'{\"uri\": \"https://arxiv.org/pdf/2407.21783\", \"name\": \"Llama 3.1 pretraining corpus (inherited from base model)\", \"size\": \"about 15T tokens (family-level, per Llama 3 Herd technical report)\", \"modality\": \"text\", \"provider\": \"Meta\", \"description\": \"Undisclosed multilingual/code/math pretraining mixture used to train the base meta-llama/Llama-3.1-8B-Instruct model; not modified by this fine-tuning, listed for lineage completeness.\"}'),('slug:medqwen-7b-lora-chinese-medical-dialogue-30284',NULL,'finetuning,evaluation','[\"converted to Qwen2.5 chat template (system/user/assistant roles)\"]',NULL,378,'{\"name\": \"MedQwen-7B-LoRA Chinese medical dialogue pairs (30,284)\", \"size\": \"30,284 pairs\", \"modality\": \"text\", \"provider\": \"mellee030\", \"description\": \"30,284 Chinese medical Q&A dialogue pairs covering symptoms, medications, diseases, and treatment advice; converted to the Qwen2.5 chat template format (system/user/assistant).\"}'),('slug:mgsm','b2f13d426afe3be8d69a7e739b36724db8b66bbc','evaluation',NULL,'CC BY-SA 4.0',391,'{\"uri\": \"https://huggingface.co/datasets/juletxara/mgsm\", \"name\": \"Multilingual MGSM (CoT)\", \"size\": \"250 test examples per language across 11 languages (2,750 total)\", \"hf_id\": \"juletxara/mgsm\", \"provider\": \"Google Research\", \"description\": \"The same 250 GSM8K grade-school math problems professionally translated into 10 languages (plus English) for evaluating multilingual chain-of-thought reasoning.\", \"hf_last_modified\": \"2026-05-04\"}'),('slug:multipl-e','28441b6024e71d4a1c1c0f6bf171c935cd5a43f2','evaluation',NULL,'MIT',384,'{\"uri\": \"https://huggingface.co/datasets/nuprl/MultiPL-E\", \"name\": \"Multipl-E HumanEval\", \"size\": \"Varies by language/config (e.g. humaneval-adb: 157 test examples); 22 languages total across HumanEval and MBPP source sets\", \"hf_id\": \"nuprl/MultiPL-E\", \"provider\": \"Northeastern University Programming Research Lab (nuprl)\", \"description\": \"A dataset for evaluating code generation LLMs that translates the OpenAI HumanEval and MBPP benchmarks into 22 programming languages using automated compiler-based translation.\", \"hf_last_modified\": \"2025-07-15\"}'),('slug:nexus','85c7c326fcfb9c6587daabd9582e7cfaddcc65bd','evaluation',NULL,'CC-BY-NC-4.0',390,'{\"uri\": \"https://huggingface.co/datasets/Nexusflow/NexusRaven_API_evaluation\", \"name\": \"Nexus\", \"size\": \"348 examples (outputs_in_toolllm_format), plus raw/standardized API list and query configs (65 APIs, 318-339 queries)\", \"hf_id\": \"Nexusflow/NexusRaven_API_evaluation\", \"provider\": \"Nexusflow\", \"description\": \"Evaluation dataset used for the NexusRaven function-calling benchmark, combining Nexusflow-curated real-world API queries (CVE/CPE, VirusTotal, etc.) with general-domain ToolLLM/ToolAlpaca samples.\", \"hf_last_modified\": \"2023-09-29\"}'),('slug:or-bench-80k','e36d8b80e81837c8a8f264bbb2a49f1b32c7e272','evaluation',NULL,'CC-BY-4.0',377,'{\"uri\": \"https://huggingface.co/datasets/bench-llm/or-bench\", \"name\": \"OR-Bench 80K (refusal rate)\", \"size\": \"80,000 prompts (or-bench-80k.csv config)\", \"hf_id\": \"bench-llm/or-bench\", \"provider\": \"OR-Bench paper authors (Cui et al.)\", \"description\": \"80,000 seemingly-toxic but actually benign prompts across 10 common rejection categories, used to measure LLM over-refusal behavior; part of the larger OR-Bench collection (also includes OR-Bench-Hard-1K and OR-Bench-Toxic configs).\", \"hf_last_modified\": \"2024-12-19\"}'),('slug:quac','2c1b73f07a629a338127b6a9761c64bf3e969179','evaluation',NULL,'MIT',398,'{\"uri\": \"https://huggingface.co/datasets/allenai/quac\", \"name\": \"QuAC\", \"size\": \"11,567 train / 1,000 validation dialogs (~100,000 questions total)\", \"hf_id\": \"allenai/quac\", \"provider\": \"Allen Institute for AI (AI2)\", \"description\": \"A dataset for question answering in context containing information-seeking dialogs between a student and teacher over hidden Wikipedia text, with ~100K questions total across 14K dialogs.\", \"hf_last_modified\": \"2024-01-18\"}'),('slug:qwen2.5-1m-long-context-synthesis',NULL,'finetuning','[\"fill-in-the-middle synthesis\", \"keyword/position-based retrieval synthesis\", \"paragraph reordering\"]',NULL,405,'{\"name\": \"Qwen2.5-1M long-context synthetic training data\", \"modality\": \"text\", \"provider\": \"Qwen Team (Alibaba Cloud)\", \"description\": \"Synthesized long-document data for progressive context-length pretraining and long-context SFT, built via fill-in-the-middle tasks, keyword/position-based retrieval tasks, and paragraph reordering to teach long-range dependency modeling.\"}'),('slug:qwen2.5-post-training-mixture',NULL,'finetuning',NULL,NULL,407,'{\"name\": \"Qwen2.5 post-training (SFT + RL) data mixture\", \"size\": \">1M SFT samples plus multistage RL preference data (exact composition undisclosed)\", \"modality\": \"text\", \"provider\": \"Qwen Team (Alibaba Cloud)\", \"description\": \"Instruction-tuning and alignment data mixture used to turn the Qwen2.5-7B base checkpoint into Qwen2.5-7B-Instruct; the technical report states this stage used supervised fine-tuning with over 1 million samples plus multistage reinforcement learning (offline and online RL / DPO-style preference optimization), covering chat-format instructions, structured output (e.g. JSON) tasks, role-play, and long-text generation, but does not disclose the exact source composition.\"}'),('slug:qwen2.5-pretraining-corpus',NULL,'pretraining',NULL,NULL,406,'{\"name\": \"Qwen2.5 pretraining corpus\", \"size\": \"up to 18T tokens\", \"modality\": \"text\", \"provider\": \"Qwen Team (Alibaba Cloud)\", \"description\": \"Large-scale multilingual (29+ languages) pretraining corpus covering general web text, code, and mathematics; the technical report states specialized expert models were used to generate additional high-quality coding and math data, but the exact dataset inventory, sourcing, and filtering/dedup pipeline are not publicly disclosed.\"}'),('slug:squad','7b6d24c440a36b6815f21b70d25016731768db1f','evaluation',NULL,'CC BY-SA 4.0',397,'{\"uri\": \"https://huggingface.co/datasets/rajpurkar/squad\", \"name\": \"SQuAD\", \"size\": \"10,570 validation examples (87,599 train)\", \"hf_id\": \"rajpurkar/squad\", \"provider\": \"Stanford University\", \"description\": \"A reading comprehension dataset of questions posed by crowdworkers on Wikipedia articles, where the answer is a span of text from the corresponding passage.\", \"hf_last_modified\": \"2024-03-04\"}'),('slug:synthetic_alpaca','2031502bdf5a046b437ec835c6b05ff468aa0699','finetuning','[\"random selection of injected instruction from another sample\", \"randomized injection position (start/end/completion)\", \"self-generated desirable response from benign prompt\", \"self-generated undesirable response from injected instruction\", \"recursive filtering of special delimiter tokens from untrusted data\"]',NULL,361,'{\"uri\": \"https://github.com/facebookresearch/Meta_SecAlign/blob/main/secalign_plus_plus.py\", \"name\": \"synthetic_alpaca (SecAlign++ preference dataset)\", \"size\": \"19,157 samples\", \"modality\": \"text\", \"provider\": \"FAIR at Meta / UC Berkeley (SecAlign++ recipe authors), derived from gururise/AlpacaDataCleaned\", \"description\": \"DPO preference dataset built from the Cleaned-Alpaca instruction-tuning dataset: samples with a data part are augmented with simulated prompt injections (straightforward attacks randomly placed at the start or end of data in ~45%/45% of cases, completion attacks in ~10%), and desirable/undesirable responses are self-generated by the initialization model (rather than using the original dataset\'s low-quality TEXT_DAVINCI_003 labels), per the SecAlign++ recipe.\"}'),('slug:triviaqa-wiki','0f7faf33a3908546c6fd5b73a660e0f8ff173c2f','evaluation',NULL,'Apache-2.0',396,'{\"uri\": \"https://huggingface.co/datasets/mandarjoshi/trivia_qa\", \"name\": \"TriviaQA-Wiki\", \"size\": \"61,888 train / 7,993 validation examples (rc.wikipedia config)\", \"hf_id\": \"mandarjoshi/trivia_qa\", \"provider\": \"University of Washington\", \"description\": \"A reading comprehension dataset of trivia question-answer pairs with distantly supervised evidence documents; the \'wikipedia\' config restricts evidence to Wikipedia pages.\", \"hf_last_modified\": \"2024-01-05\"}'),('truthfulqa/truthful_qa','741b8276f2d1982aa3d5b832d3ee81ed3b896490','evaluation',NULL,'Apache-2.0',371,'{\"uri\": \"https://aclanthology.org/2022.acl-long.229\", \"name\": \"TruthfulQA\", \"size\": \"817 questions, 38 categories\", \"hf_id\": \"truthfulqa/truthful_qa\", \"modality\": \"text\", \"provider\": \"Stephanie Lin, Jacob Hilton, Owain Evans\", \"description\": \"Original English benchmark of questions designed to elicit imitative falsehoods (Lin, Hilton, Evans, 2022); source of the base questions extended by TruthfulQA-Multi.\", \"hf_last_modified\": \"2024-01-04\"}');
