INSERT INTO `evaluation` VALUES (913,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"shots\": 0, \"benchmark\": \"MMLU\", \"model_tested\": \"official META-SECALIGN-8B (SecAlign++ on Llama-3.1-8B-Instruct)\"}','acc',71.7000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 72.0}'),(914,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"shots\": 5, \"benchmark\": \"MMLU-Pro\", \"model_tested\": \"official META-SECALIGN-8B\"}','acc',46.7000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 46.5}'),(915,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"benchmark\": \"IFEval\", \"model_tested\": \"official META-SECALIGN-8B\"}','acc',74.5000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 79.1}'),(916,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"shots\": 3, \"benchmark\": \"BBH\", \"model_tested\": \"official META-SECALIGN-8B\"}','acc',70.9000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 71.9}'),(917,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"benchmark\": \"GPQA Diamond\", \"model_tested\": \"official META-SECALIGN-8B\"}','acc',28.3000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 31.3}'),(918,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"notes\": \"805 AlpacaFarm samples, judged by GPT-4o\", \"benchmark\": \"AlpacaEval2\", \"model_tested\": \"official META-SECALIGN-8B\"}','utility/win_rate_vs_GPT-4',31.0000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 31.2, \"evaluator_model\": \"gpt-4o-2024-05-13\"}'),(919,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"benchmark\": \"SEP\", \"model_tested\": \"official META-SECALIGN-8B\"}','utility/win_rate_vs_Llama3-8B-Instruct',48.8000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 51.4}'),(920,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"attack\": \"6 non-adaptive PI techniques (straightforward/ignore/completion)\", \"benchmark\": \"AlpacaFarm\", \"model_tested\": \"official META-SECALIGN-8B\"}','ASR',0.0000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"score_text\": \"0%\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 68.3}'),(921,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"attack\": \"adaptive fake-delimiter completion / completion-ignore attacks\", \"benchmark\": \"AlpacaFarm\", \"model_tested\": \"official META-SECALIGN-8B\"}','ASR_basic_adaptive',0.5000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 89.4}'),(922,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"attack\": \"GCG white-box adaptive attack\", \"benchmark\": \"AlpacaFarm\", \"model_tested\": \"official META-SECALIGN-8B\"}','ASR_GCG_adaptive',20.7000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 87.0}'),(923,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"attack\": \"6 non-adaptive PI techniques, witness-word detection\", \"benchmark\": \"SEP\", \"model_tested\": \"official META-SECALIGN-8B\"}','ASR',7.8000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 98.1}'),(924,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"benchmark\": \"SEP\", \"model_tested\": \"official META-SECALIGN-8B\"}','ASR_basic_adaptive',11.5000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 97.1}'),(925,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"notes\": \"31K samples, GPT-4o judge\", \"benchmark\": \"TaskTracker\", \"model_tested\": \"official META-SECALIGN-8B\"}','ASR',0.2000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 12.4, \"evaluator_model\": \"gpt-4o\"}'),(926,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"notes\": \"55 indirect PI samples, GPT-4o judge\", \"benchmark\": \"CyberSecEval2\", \"model_tested\": \"official META-SECALIGN-8B\"}','ASR',7.3000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 21.8, \"evaluator_model\": \"gpt-4o\"}'),(927,'FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp',NULL,'{\"notes\": \"1K API-calling samples, sandwich (repeat_user_prompt) defense applied\", \"benchmark\": \"InjecAgent\", \"model_tested\": \"official META-SECALIGN-8B\"}','ASR_total_with_sandwich_defense',0.0000,'2026-02-06','{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"score_text\": \"0%\", \"baseline_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"baseline_score\": 15.1}'),(940,'HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge','HiTZ/truthful_judge','{\"notes\": \"Per model card, citing paper Table 4\", \"language\": \"eu (Basque)\", \"benchmark\": \"TruthfulQA-Multi (Judge agreement, Cohen\'s Kappa vs human judgment)\", \"training_data\": \"MT data (all languages except English)\"}','cohen_kappa',0.5100,'2025-05-27','{\"reference\": \"https://huggingface.co/HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge\", \"evaluator_model\": \"HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge\"}'),(941,'HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge','HiTZ/truthful_ju