INSERT INTO `model` VALUES ('FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp','{\"family\": \"decoder-only Transformer (Llama 3.1 8B backbone + LoRA adapter)\", \"layers\": 32, \"ffn_size\": 14336, \"kv_heads\": 8, \"activation\": \"SwiGLU\", \"rope_theta\": 500000, \"hidden_size\": 4096, \"context_length\": 131072, \"attention_heads\": 32, \"parameter_count\": 8030261248, \"position_embedding\": \"RoPE\"}','{\"name\": \"tiktoken-based BPE (Llama 3 tokenizer, inherited from base model, unchanged by adapter)\", \"vocab_size\": 128256}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\"]}','PEFT LoRA adapter that must be loaded on top of meta-llama/Llama-3.1-8B-Instruct to make it resistant to (indirect) prompt injection attacks embedded in untrusted input data, while preserving the base model\'s instruction-following utility, following the SecAlign++ training recipe from the Meta SecAlign paper.','[\"resistance to indirect prompt injection in the new \'input\' message role\", \"preserves general instruction-following, tool-calling and agentic-workflow utility of the base model\", \"test-time security/utility trade-off tuning via LoRA alpha scaling\"]','[\"does not defend against jailbreaks or direct prompt injection (malicious user, not malicious environment)\", \"still vulnerable to strong adaptive/white-box attacks (e.g. GCG, embedding-based fake-delimiter attacks)\", \"third-party reproduction of the SecAlign++ recipe, not the official facebook/Meta-SecAlign-8B release; uses LoRA rank 32 vs. rank 64 in the paper\'s official 8B recipe\", \"must be used with the exact SecAlign++ chat template (added \'input\' role) to be effective; misuse of the template negates the defense\"]',408,'{\"evidence\": [1, 2, 55, 56, 57, 59, 60], \"unknowns\": [\"Exact number of LoRA adapter trainable parameters (not stated in card or config)\", \"Whether lora_dropout was used in training (adapter_config.json omits the field; the paper\'s SecAlign++ recipe default is 0.1)\", \"Whether this adapter\'s own security/utility numbers match the official META-SECALIGN-8B numbers reported in arXiv:2507.02735, given the LoRA rank differs (32 here vs. 64 in the official 8B recipe) — no independent evaluation of this specific repo was found\", \"AgentDojo and WASP (agentic workflow) ASR/utility numbers specifically for the 8B model (the paper only reports these benchmarks in detail for the 70B model)\", \"Exact training date and hardware used for this specific adapter (only the HF repo creation/last-modified date, 2026-03-02, is available)\", \"Whether the \'SecUnalign-pp\' companion adapter mentioned in the card is by the same author or officially affiliated\"], \"release_date\": \"2026-03-02\", \"knowledge_cutoff\": \"2023-12\"}'),('FreedomIntelligence/HuatuoGPT-o1-8B','{\"family\": \"decoder-only Transformer (Llama 3.1 architecture)\", \"layers\": 32, \"ffn_size\": 14336, \"head_dim\": 128, \"kv_heads\": 8, \"activation\": \"SwiGLU (silu)\", \"rope_theta\": 500000, \"hidden_size\": 4096, \"rope_scaling\": {\"factor\": 8.0, \"rope_type\": \"llama3\", \"low_freq_factor\": 1.0, \"high_freq_factor\": 4.0, \"original_max_position_embeddings\": 8192}, \"attention_type\": \"grouped-query attention\", \"context_length\": 131072, \"attention_heads\": 32, \"parameter_count\": 8030261248, \"position_embedding\": \"RoPE\"}','{\"name\": \"tiktoken-based BPE (Llama 3 tokenizer), PreTrainedTokenizerFast\", \"vocab_size\": 128256}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\"]}','A medical LLM fine-tuned from Llama-3.1-8B-Instruct for advanced medical reasoning: it generates a complex \'Thinking\' trace (reflecting, backtracking, and correcting itself) before producing a \'Final Response\' to medical questions.','[\"complex multi-step medical reasoning\", \"self-reflection and correction of reasoning trajectories (thinks-before-it-answers)\", \"structured \'## Thinking\' / \'## Final Response\' output format\", \"medical exam question answering (USMLE-style)\"]','[\"not suitable for real-world clinical or industry applications where inaccuracies could cause harm (per paper\'s ethical statement)\", \"may still produce hallucinated or inaccurate medical content\", \"trained/evaluated only on English medical benchmarks (this 8B checkpoint)\", \"verifier (GPT-4o) used to build training data is itself imperfect (~94.5-96.5% measured accuracy), so some training signal may be noisy\"]',421,'{\"evidence\": [4, 6, 8, 61, 62, 63, 67], \"unknowns\": [\"Exact training/compute infrastructure, total GPU-hours, and full hyperparameter set beyond the stage-level SFT/PPO values disclosed in the paper\", \"Exact revision/commit-level provenance tying the released HF checkpoint to a specific training run\", \"Precise size (row count) of the currently distributed medical-o1-reasoning-SFT dataset revision after its 2025-04-22 split into medical-only vs. mixed files; paper describes 20K SFT examples but the live dataset card does not restate an exact count\", \"Model\'s exact knowledge cutoff date (inherits from Llama-3.1-8B-Instruct pretraining cutoff of late 2023, but not independently restated for this model)\", \"Whether any additional safety/red-teaming evaluation specific to this checkpoint was performed beyond the verifier-reliability check described in the paper\"], \"release_date\": \"2024-12-27\"}'),('HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO','{\"family\": \"decoder-only Transformer (Qwen2ForCausalLM)\", \"layers\": 28, \"ffn_size\": 18944, \"kv_heads\": 4, \"activation\": \"SwiGLU\", \"rope_theta\": 1000000, \"hidden_size\": 3584, \"normalization\": \"RMSNorm\", \"attention_type\": \"grouped-query attention with QKV bias\", \"context_length\": 32768, \"attention_heads\": 28, \"parameter_count\": 7615616512, \"position_embedding\": \"RoPE\"}','{\"name\": \"Qwen2Tokenizer (BPE)\", \"vocab_size\": 152064}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\"]}','Safety-hardened conversational assistant derived from Qwen2.5-7B-Instruct, DPO-tuned to be more resistant to jailbreaking/adversarial prompts while retaining general instruction-following ability; intended as a research artifact and drop-in safer replacement for the base instruct model.','[\"general instruction following inherited from Qwen2.5-7B-Instruct\", \"reduced attack success rate against tested jailbreak prompt sets\", \"English-language safety-aligned dialogue\"]','[\"MMLU accuracy decreased versus the untuned baseline (0.331 -> 0.296 per the model card)\", \"Refusal rate on OR-Bench 80K increased slightly (0.021 -> 0.029), i.e. modest over-refusal\", \"Safety gains are benchmark-specific (Egida test, DELPHI, Alert-Base, Alert-Adv); robustness against unseen jailbreak styles is not established\", \"Max context length in the released config.json is 32,768 tokens (no rope_scaling entry found), narrower than the 131,072-token long-context support documented for Qwen2.5-7B-Instruct\"]',411,'{\"evidence\": [15, 16, 19, 77, 78, 81], \"unknowns\": [\"Exact DPO beta value and number of training epochs are not disclosed on the model card or in the paper text retrieved.\", \"Whether full-parameter fine-tuning or a PEFT/LoRA method was used for the DPO run is not explicitly stated (released safetensors total 7.615B parameters, consistent with a full fine-tune of the base model).\", \"Baseline (pre-tuning) OpenLLM average score is not given numerically, only that it \'remained stable\' near the reported 0.488 post-tuning value.\", \"Knowledge cutoff of the underlying Qwen2.5-7B-Instruct base model is not restated on this derived model\'s card.\", \"config.json for this repo shows max_position_embeddings=32768 with no rope_scaling field, so it is unverified whether the 131,072-token long-context behavior documented for Qwen2.5-7B-Instruct (via YaRN) is retained after DPO tuning.\", \"Exact HF dataset ids for the DELPHI and ALERT (Alert-Base/Alert-Adv) external benchmarks could not be independently verified from the sources opened, so evaluations[].dataset_key is left null for those rows.\", \"Precise identity/HF id of the \'OR-Bench 80K\' benchmark subset could not be independently verified; dataset_key uses a provisional slug.\"], \"release_date\": \"2025-02-18\"}'),('HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge','{\"family\": \"decoder-only Transformer (Llama 3.1 architecture)\", \"layers\": 32, \"ffn_size\": 14336, \"kv_heads\": 8, \"activation\": \"SiLU/SwiGLU\", \"rope_theta\": 500000, \"hidden_size\": 4096, \"context_length\": 131072, \"attention_heads\": 32, \"parameter_count\": 8030261248, \"position_embedding\": \"RoPE (llama3 rope_scaling, factor 8.0)\"}','{\"name\": \"Llama 3 tokenizer, tiktoken-based BPE (PreTrainedTokenizerFast)\", \"vocab_size\": 128257}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\", \"es\", \"ca\", \"gl\", \"eu\"]}','LLM-as-a-Judge that takes a question, a reference answer, and a candidate model-generated answer and outputs a Yes/No judgment of whether the candidate answer is truthful, used to evaluate models on the multilingual TruthfulQA-Multi benchmark (English, Basque, Catalan, Galician, Spanish).','[\"binary truthfulness judgment of QA answers\", \"multilingual evaluation (en/es/ca/gl/eu)\", \"automated fact-checking / benchmark scoring support\"]','[\"not designed for general-purpose creative text or dialogue generation\", \"does not provide factual information directly, only judges\", \"not validated for safety-critical use\", \"performance varies by language (weaker on culturally specific / time-dependent questions)\", \"inherits biases and imitative-falsehood framing from original TruthfulQA\"]',410,'{\"evidence\": [10, 11, 14, 69, 70, 73, 74, 75], \"unknowns\": [\"Exact batch size and optimizer used for fine-tuning (model card says \'refer to project code\'; not found in fetched GitHub README excerpt)\", \"Exact number of training instances in the \'multi\' config (finetune_truth_multi.json) and per-language breakdown\", \"Whether an English-language Kappa/Spearman score exists for this exact model (card and paper Table 4 report scores only for eu/ca/gl/es, described as trained on \'MT data (all languages except English)\', despite the model card\'s language list including English)\", \"Training hardware/compute used\", \"Exact license file wording on the HF repo (page shows tag \'license:llama3.1\' while model card body states fine-tuned weights are Apache-2.0; both stated as-is, not reconciled by an inspected LICENSE file)\", \"Independent verification of full paper Table 3 vs Table 4 contents was inconsistent across automated fetches of the arXiv HTML; evaluation numbers here are taken directly from the model card\'s own quoted Table 4 values rather than re-derived from the paper PDF/HTML\"], \"release_date\": \"2025-05-27\", \"knowledge_cutoff\": \"2023-12\"}'),('NousResearch/Hermes-3-Llama-3.1-8B','{\"family\": \"decoder-only Transformer (Llama 3.1 architecture)\", \"layers\": 32, \"ffn_size\": 14336, \"kv_heads\": 8, \"activation\": \"SwiGLU\", \"rope_theta\": 500000.0, \"hidden_size\": 4096, \"rope_scaling\": {\"factor\": 8.0, \"rope_type\": \"llama3\", \"low_freq_factor\": 1.0, \"high_freq_factor\": 4.0, \"original_max_position_embeddings\": 8192}, \"context_length\": 131072, \"attention_heads\": 32, \"parameter_count\": 8030261248, \"position_embedding\": \"RoPE\"}','{\"name\": \"PreTrainedTokenizerFast, tiktoken-based BPE (Llama 3.1 tokenizer) with additional Hermes/ChatML special tokens (e.g. <|im_start|>, <|im_end|>, <SCRATCHPAD>, <REASONING>, <INNER_MONOLOGUE>, <PLAN>, <EXECUTION>, <REFLECTION>, <THINKING>, <SOLUTION>, <EXPLANATION>, <UNIT_TEST>)\", \"vocab_size\": 128256}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\"]}','A neutrally-aligned, highly steerable generalist instruct and tool-use assistant for reasoning, coding, roleplaying, agentic tool use, structured/JSON output, and multi-turn conversation, obedient to system-prompt persona and instructions.','[\"instruction following\", \"multi-turn conversation with 128K context coherence\", \"function/tool calling via Hermes Function Calling standard\", \"JSON mode / structured outputs\", \"roleplaying and persona adoption\", \"agentic planning with scratchpad/reasoning tags\", \"retrieval-augmented generation with citation tags\", \"code generation and explanation\", \"LLM-as-judge style evaluation/reward modeling\"]','[\"highly sensitive to system prompt; behavior can diverge substantially depending on persona instructions\", \"neutral alignment means the model will follow instructions with fewer built-in moral refusals, shifting responsibility for guardrails to the deploying system\", \"inherits base-model knowledge cutoff and any biases/limitations of Llama 3.1 8B\", \"DPO phase gave only moderate benchmark gains for the 8B size versus SFT alone\"]',417,'{\"evidence\": [25, 74, 119, 120, 121, 122, 125, 126], \"unknowns\": [\"Exact per-sample inventory / mixture ratios of the Hermes 3 SFT dataset beyond the 8 disclosed category proportions and token counts\", \"Composition and size of the DPO preference dataset (only the LoRA/optimizer hyperparameters and aggregate benchmark impact are disclosed)\", \"Exact repository creation vs public release date distinction (HF createdAt 2024-07-28 used as release_date; paper published 2024-08-15)\", \"Whether any additional model averaging/merging was applied to the released 8B artifact (model averaging is listed in prior catalog notes but not confirmed in the technical report text for the 8B specifically)\", \"Full context on why the model card\'s own model-index metadata field is populated with \'Hermes-3-Llama-3.1-70B\' instead of the 8B model\"], \"release_date\": \"2024-07-28\", \"knowledge_cutoff\": \"end of 2023 (inherited from Llama 3.1 base pretraining)\"}'),('Qwen/Qwen2.5-7B','{\"family\": \"decoder-only Transformer (Qwen2 architecture)\", \"layers\": 28, \"ffn_size\": 18944, \"kv_heads\": 4, \"activation\": \"SwiGLU\", \"rope_theta\": 1000000, \"hidden_size\": 3584, \"normalization\": \"RMSNorm\", \"attention_bias\": \"QKV bias\", \"attention_type\": \"grouped-query attention\", \"context_length\": 131072, \"attention_heads\": 28, \"parameter_count\": 7615616512, \"position_embedding\": \"RoPE\"}','{\"name\": \"Qwen2Tokenizer, byte-level BPE (tiktoken-derived)\", \"vocab_size\": 152064}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\", \"zh\", \"fr\", \"es\", \"pt\", \"de\", \"it\", \"ru\", \"ja\", \"ko\", \"vi\", \"th\", \"ar\"]}','Base causal language model intended as a foundation for further post-training (SFT, RLHF/DPO, continued pretraining) rather than direct conversational use.','[\"long-context modeling up to 131,072 tokens\", \"multilingual text generation (29+ languages)\", \"strong performance on coding and mathematics benchmarks relative to prior Qwen2 generation\"]','[\"not recommended for direct conversational/instruction-following use without further post-training\", \"non-embedding parameter count (6.53B) differs from total (7.61B) due to the large 152K-token vocabulary embedding table\"]',420,'{\"evidence\": [29, 30, 139, 140, 141], \"unknowns\": [\"Exact pretraining dataset inventory/sources (only aggregate 18T-token figure disclosed)\", \"Knowledge cutoff date is not stated in the HF card, blog, or technical report abstract/tables reviewed\", \"Exact data processing/filtering/dedup pipeline for the pretraining corpus\", \"Pretraining hyperparameters (learning rate schedule, batch size, optimizer, hardware)\", \"MMLU-redux, TheoremQA, MMLU-STEM, HumanEval+, MBPP+, MultiPL-E have no canonical HF dataset id in the fixed convention list, so dataset_key is null for these evaluation rows even though the benchmarks are well known\"], \"release_date\": \"2024-09-19\"}'),('Qwen/Qwen2.5-7B-Instruct','{\"family\": \"decoder-only Transformer (Qwen2 architecture)\", \"layers\": 28, \"ffn_size\": 18944, \"kv_heads\": 4, \"activation\": \"SwiGLU\", \"rope_theta\": 1000000, \"hidden_size\": 3584, \"normalization\": \"RMSNorm\", \"attention_bias\": \"QKV bias\", \"attention_type\": \"grouped-query attention\", \"context_length\": 131072, \"attention_heads\": 28, \"parameter_count\": 7615616512, \"position_embedding\": \"RoPE\"}','{\"name\": \"Qwen2Tokenizer, byte-level BPE (tiktoken-derived)\", \"vocab_size\": 152064}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\", \"zh\", \"fr\", \"es\", \"pt\", \"de\", \"it\", \"ru\", \"ja\", \"ko\", \"vi\", \"th\", \"ar\"]}','General-purpose multilingual chat assistant supporting instruction following, long-form generation, structured/JSON output, and role-play, built for direct conversational and downstream-adaptation use.','[\"instruction following\", \"long-context understanding and generation (up to 131,072 tokens with YaRN scaling; 32,768-token native window in the shipped config.json)\", \"structured data understanding and JSON generation\", \"multilingual chat (29+ languages)\", \"coding and mathematics assistance\"]','[\"shipped config.json defaults to a 32,768-token context window; extending to the full 131,072-token window requires manually enabling YaRN rope_scaling, which vLLM applies only statically and can reduce short-text performance\", \"refusal ratio and safety behavior beyond the reported benchmarks are not independently characterized in the reviewed sources\"]',419,'{\"evidence\": [29, 30, 81, 86, 135, 136], \"unknowns\": [\"Exact SFT/RL dataset composition and sizes beyond the aggregate \'>1M SFT samples plus multistage RL\' description\", \"Knowledge cutoff date is not stated in the HF card, blog, or technical report abstract/tables reviewed\", \"Per-stage post-training hyperparameters (learning rates, RL algorithm/reward model details)\", \"MMLU-redux and LiveCodeBench/LiveBench have no canonical HF dataset id in the fixed convention list, so dataset_key is null for these evaluation rows\"], \"release_date\": \"2024-09-19\"}'),('Qwen/Qwen2.5-7B-Instruct-1M','{\"family\": \"dense decoder-only Transformer\", \"layers\": 28, \"ffn_size\": 18944, \"kv_heads\": 4, \"activation\": \"SwiGLU\", \"rope_theta\": 10000000, \"hidden_size\": 3584, \"normalization\": \"RMSNorm\", \"context_length\": 1010000, \"sliding_window\": 32768, \"attention_heads\": 28, \"parameter_count\": 7610000000, \"attention_bias_qkv\": true, \"position_embedding\": \"RoPE\", \"dual_chunk_attention_chunk_size\": 262144, \"dual_chunk_attention_local_window\": 8192}','{\"name\": \"Qwen2Tokenizer, BPE-based\", \"vocab_size\": 152064}','{\"input\": [\"text\"], \"output\": [\"text\"]}','General-purpose instruction-following chat/text-generation model specialized for ultra-long-context tasks (up to ~1M tokens) while retaining short-context capability, using a custom vLLM deployment with sparse attention and length extrapolation for efficient long-sequence inference.','[\"up to 1,010,000-token context handling\", \"8192-token generation length\", \"chat / instruction following\", \"long-document retrieval and reasoning (RULER, LV-Eval, LongBench-Chat)\", \"short-context general capability retained (MMLU-Pro, GSM8K, HumanEval, etc.)\", \"3-7x inference speedup on long sequences via custom sparse-attention vLLM\"]','[\"requires >=120GB VRAM (multi-GPU, Ampere/Hopper) to process near-1M-token inputs\", \"accuracy degradation may occur beyond 262,144 tokens when run with standard (non-sparse) attention frameworks\", \"minor regressions vs 128K sibling on some short-context benchmarks (e.g. MMLU-Pro, MATH, MBPP, Arena-Hard, MTbench)\"]',418,'{\"evidence\": [28, 127, 128, 129, 130, 132], \"unknowns\": [\"Exact identity of the \'intermediate checkpoint of pre-trained Qwen2.5 (4K context)\' used as the true starting point for long-context training; it is not a separately released HF model_id, so provenance.inputs cites the closest declared/public artifact (Qwen/Qwen2.5-7B) with a note explaining the discrepancy.\", \"Knowledge cutoff date for Qwen2.5-7B-Instruct-1M (not stated on the model card or in the technical report excerpt reviewed).\", \"Exact size (token/example count) of the long-context synthetic training data used in progressive pretraining and long-context SFT.\", \"RULER scores for individual context lengths beyond 128K (256K, 512K, 1M) for the 7B model specifically; only the aggregate Avg (84.4) reflects them.\", \"Whether languages beyond English are officially claimed for this specific 1M checkpoint (the model card\'s YAML lists English; broader Qwen2.5 family multilingual claims were not reverified against this specific model\'s card).\"], \"release_date\": \"2025-01-26\"}'),('mellee030/MedQwen-7B-LoRA','{\"family\": \"decoder-only Transformer (Qwen2.5 architecture); LoRA adapter on frozen base weights\", \"layers\": 28, \"ffn_size\": 18944, \"kv_heads\": 4, \"activation\": \"SwiGLU\", \"rope_theta\": 1000000, \"hidden_size\": 3584, \"context_length\": 32768, \"attention_heads\": 28, \"position_embedding\": \"RoPE\"}','{\"name\": \"Qwen2Tokenizer (BPE), inherited unchanged from Qwen2.5-7B-Instruct\", \"vocab_size\": 152064}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"zh\"]}','Domain-adapted Chinese medical question-answering / dialogue assistant, produced by LoRA fine-tuning Qwen2.5-7B-Instruct on Chinese medical Q&A pairs.','[\"Chinese medical Q&A (symptoms, medications, diseases, treatment advice)\", \"concise, on-format chat-style answers\", \"retains base Qwen2.5-7B-Instruct general instruction-following via frozen base weights\"]','[\"Intended for Chinese medical Q&A only\", \"Not a substitute for professional medical advice\", \"Performance may vary on medical topics underrepresented in the training data\", \"Evaluated only on a specific, undisclosed Chinese medical Q&A corpus (412 held-out samples, 50-sample subset scored); results may differ on other datasets\"]',412,'{\"evidence\": [21, 81, 83, 84, 86, 87], \"unknowns\": [\"Exact number of trainable LoRA parameters (only artifact size ~150MB / \'~1% of parameters\' is reported; base Qwen2.5-7B-Instruct has 7.61B parameters, 6.53B non-embedding per its own card).\", \"Exact release/publish date of the adapter; used HF repo createdAt (2026-04-17T17:15:06Z, per the Hub API) as a proxy since the card gives no explicit date.\", \"Precise composition/provenance of the \'30,284 Chinese medical dialogue pairs\' training set: no dataset name, license, or public source is given on the HF card. The linked GitHub repo (github.com/melc030/MedQwen) describes what appears to be a related/evolved version of the same personal project, but its current README documents a different configuration (Qwen2.5-1.5B-Instruct base, LoRA r=16/alpha=32, ~43K pairs derived from an 8,807-disease template-generated set and a \'medgraphrag_qa_clean\' split) — these numbers do not match the 7B adapter\'s r=8/alpha=16/30,284-pair configuration, so the repo could not be used to confirm the exact dataset behind this specific model; treated as directionally related evidence only, not as a confirmed source.\", \"Whether ROUGE was computed with character-level tokenization for Chinese (confirmed for the related 1.5B project in the GitHub README) also applies identically to this 7B adapter\'s reported numbers; not explicitly restated on the 7B model card.\", \"Author\'s real-world identity/organization behind the HF account \'mellee030\' and GitHub account \'melc030\'.\", \"Whether the base_model_name_or_path in adapter_config.json (\'/home/yuxincui/MedQwen/Qwen2.5-7B-Instruct\', a local path referencing a \'yuxincui\' user) indicates the actual author\'s name is separate from the HF/GitHub handles used.\", \"Knowledge cutoff date of the underlying base model / adapter training data.\", \"The \'top\' dataset name/URL surfaced in the catalog\'s automated CycloneDX checklist (datasetNames: [\'top\'], https://huggingface.co/datasets/top) does not correspond to any dataset referenced in the HF card\'s YAML front-matter or body text; treated as a checklist extraction artifact and omitted from datasets[].\"], \"release_date\": \"2026-04-17\"}'),('meta-llama/Llama-3.1-8B','{\"family\": \"decoder-only Transformer\", \"layers\": 32, \"ffn_size\": 14336, \"head_dim\": 128, \"kv_heads\": 8, \"activation\": \"SwiGLU\", \"rope_theta\": 500000, \"hidden_size\": 4096, \"rope_scaling\": {\"factor\": 8.0, \"rope_type\": \"llama3\", \"low_freq_factor\": 1.0, \"high_freq_factor\": 4.0, \"original_max_position_embeddings\": 8192}, \"attention_type\": \"grouped-query attention\", \"context_length\": 131072, \"attention_heads\": 32, \"parameter_count\": 8030261248, \"position_embedding\": \"RoPE\"}','{\"name\": \"tiktoken-based BPE (Llama 3 tokenizer)\", \"vocab_size\": 128256}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\", \"de\", \"fr\", \"it\", \"pt\", \"hi\", \"es\", \"th\"]}','Pretrained generative text model intended as a base for commercial and research use in English and other supported languages; developers can build assistant-like chat applications, natural language generation tasks, or further fine-tune it for other purposes.','[\"general-purpose text generation\", \"few-shot in-context learning\", \"base for supervised fine-tuning\", \"long-context (131072 tokens) modeling\"]','[\"not instruction-tuned out of the box\", \"may produce inaccurate, biased, or objectionable outputs\", \"primarily trained and tested in English; performance in other supported languages may vary\", \"knowledge limited to pretraining data cutoff (Dec 2023)\"]',414,'{\"evidence\": [22, 24, 74, 91, 93, 94, 95], \"unknowns\": [\"Exact pretraining compute budget (GPU-hours/FLOPs) for the 8B checkpoint specifically\", \"Full itemized list of pretraining data sources/mixture ratios (Meta discloses only high-level processing steps and aggregate token count)\", \"Exact training hyperparameters (learning rate schedule, batch size, optimizer) for the 8B model\", \"config.json for the gated meta-llama/Llama-3.1-8B repo could not be fetched directly (401 gated); architecture fields verified via the unsloth/Meta-Llama-3.1-8B mirror config.json, which matches the officially documented 8B specs (32 layers, hidden 4096, 32 heads/8 kv heads, ffn 14336, rope_theta 500000, 131072 context)\"], \"release_date\": \"2024-07-23\", \"knowledge_cutoff\": \"2023-12\"}'),('meta-llama/Llama-3.1-8B-Instruct','{\"family\": \"decoder-only Transformer\", \"layers\": 32, \"ffn_size\": 14336, \"head_dim\": 128, \"kv_heads\": 8, \"activation\": \"SwiGLU\", \"rope_theta\": 500000, \"hidden_size\": 4096, \"rope_scaling\": {\"factor\": 8.0, \"rope_type\": \"llama3\", \"low_freq_factor\": 1.0, \"high_freq_factor\": 4.0, \"original_max_position_embeddings\": 8192}, \"attention_type\": \"grouped-query attention\", \"context_length\": 131072, \"attention_heads\": 32, \"parameter_count\": 8030261248, \"position_embedding\": \"RoPE\"}','{\"name\": \"tiktoken-based BPE (Llama 3 tokenizer)\", \"vocab_size\": 128256}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\", \"de\", \"fr\", \"it\", \"pt\", \"hi\", \"es\", \"th\"]}','Instruction-tuned generative model optimized for multilingual dialogue, assistant-style chat, tool use, and agentic applications; outperforms many available open-source and closed chat models on common industry benchmarks.','[\"multi-turn dialogue / instruction following\", \"multilingual interaction (8 supported languages)\", \"tool use and function calling (API-Bank, BFCL, Gorilla, Nexus)\", \"code generation (HumanEval, MBPP, Multipl-E)\", \"mathematical reasoning (GSM8K, MATH)\", \"long-context use up to 128K tokens\"]','[\"may produce inaccurate, biased, or unsafe outputs despite safety tuning\", \"primarily evaluated/tuned in English; other supported languages may show lower quality\", \"knowledge limited to pretraining cutoff (Dec 2023)\", \"not evaluated/certified for high-risk domains without additional safeguards\"]',413,'{\"evidence\": [22, 24, 74, 89, 91, 93, 94], \"unknowns\": [\"Exact number of SFT/rejection-sampling/DPO rounds and hyperparameters used for the 8B-specific post-training run\", \"Full composition/size of the human-annotated, rejection-sampled, and synthetic post-training datasets\", \"config.json for the gated meta-llama/Llama-3.1-8B-Instruct repo could not be fetched directly (401 gated); architecture fields assumed identical to the base model and verified via the unsloth mirror config.json plus HF API metadata\", \"The current catalog entry lists this model as a \'root\' node with no parent; per task instructions its transformation input is set to meta-llama/Llama-3.1-8B (role base), consistent with HF\'s own base_model / base_model:finetune tags on the Instruct repo\"], \"release_date\": \"2024-07-23\", \"knowledge_cutoff\": \"2023-12\"}'),('mlx-community/Meta-Llama-3.1-8B-Instruct-bf16','{\"family\": \"decoder-only Transformer (dense, Llama 3 architecture, unchanged by conversion)\", \"layers\": 32, \"ffn_size\": 14336, \"kv_heads\": 8, \"attention\": \"grouped-query attention\", \"activation\": \"SwiGLU (silu)\", \"rope_theta\": 500000, \"hidden_size\": 4096, \"torch_dtype\": \"bfloat16\", \"rope_scaling\": {\"factor\": 8.0, \"rope_type\": \"llama3\", \"low_freq_factor\": 1.0, \"high_freq_factor\": 4.0, \"original_max_position_embeddings\": 8192}, \"context_length\": 131072, \"attention_heads\": 32, \"parameter_count\": 8030261248, \"position_embedding\": \"RoPE\"}','{\"name\": \"tiktoken-based BPE (Llama 3 tokenizer), PreTrainedTokenizerFast\", \"vocab_size\": 128256}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\", \"de\", \"fr\", \"it\", \"pt\", \"hi\", \"es\", \"th\"]}','MLX-format repackaging of Llama 3.1 8B Instruct (BF16 weights) for local inference on Apple silicon via mlx-lm; same general-assistant / instruction-following use case as the source model.','[\"instruction following (inherited)\", \"multilingual dialogue in 8 languages (inherited)\", \"long-context (128K) inference (inherited)\", \"tool use / function calling (inherited)\"]','[\"inherits all base-model limitations and biases (no new training)\", \"no independent safety evaluation of the converted artifact\", \"requires mlx-lm / Apple silicon runtime to load\"]',415,'{\"evidence\": [24, 74, 102, 103, 104, 105, 108, 109], \"unknowns\": [\"Exact mlx-lm conversion command and flags used\", \"Numerical-equivalence testing between the original and MLX weights\", \"Whether any of the source model\'s gated-access metadata (e.g. exact license acceptance text shown to convertor) differs from the standard Llama 3.1 Community License\", \"Precise training/pretraining dataset inventory (inherited from source, not re-disclosed in the MLX card)\"], \"release_date\": \"2024-07-23\", \"knowledge_cutoff\": \"2023-12\"}'),('mlx-community/Qwen2.5-7B-Instruct-bf16','{\"family\": \"decoder-only Transformer (dense, Qwen2 architecture, unchanged by conversion)\", \"layers\": 28, \"ffn_size\": 18944, \"kv_heads\": 4, \"attention\": \"grouped-query attention with QKV bias\", \"activation\": \"SwiGLU (silu)\", \"rope_theta\": 1000000, \"hidden_size\": 3584, \"torch_dtype\": \"bfloat16\", \"normalization\": \"RMSNorm\", \"context_length\": 32768, \"sliding_window\": 131072, \"attention_heads\": 28, \"parameter_count\": 7615616512, \"position_embedding\": \"RoPE\", \"use_sliding_window\": false}','{\"name\": \"Qwen2 byte-level BPE (Qwen2Tokenizer)\", \"vocab_size\": 152064}','{\"input\": [\"text\"], \"output\": [\"text\"], \"languages\": [\"en\"]}','MLX-format repackaging of Qwen2.5-7B-Instruct (BF16 weights) for local inference on Apple silicon via mlx-lm; same general-assistant / instruction-following use case as the source model.','[\"instruction following (inherited)\", \"long-form generation and structured/JSON output (inherited)\", \"multilingual interaction across 29+ languages per source model (inherited)\"]','[\"inherits all base-model limitations and biases (no new training)\", \"no independent safety evaluation of the converted artifact\", \"shipped config.json caps native context at 32,768 tokens; the source model\'s full 131,072-token context requires enabling YaRN RoPE scaling, which is not set in this repo\'s config.json\", \"requires mlx-lm / Apple silicon runtime to load\"]',416,'{\"evidence\": [30, 81, 86, 110, 111, 112, 113, 117, 118], \"unknowns\": [\"Exact mlx-lm conversion command and flags used\", \"Numerical-equivalence testing between the original and MLX weights\", \"Explicit knowledge cutoff date for Qwen2.5 pretraining data (not disclosed in the model card)\", \"Precise pretraining dataset inventory (inherited from source, not re-disclosed in the MLX card)\", \"Whether YaRN rope scaling is intended to be user-enabled for this MLX repo the way it is documented for the source Transformers repo\"], \"release_date\": \"2024-09-18\"}');
