 0.168, \"shots\": null, \"metric\": \"accuracy\", \"dataset\": \"slug:simpleqa\", \"benchmark\": \"SimpleQA\", \"score_text\": null, \"source_url\": \"https://arxiv.org/abs/2508.10925\", \"reported_at\": \"2025-08-05\", \"baseline_model\": null, \"baseline_score\": null, \"evaluator_model\": null, \"configuration_notes\": \"Without web browsing.\"}, {\"score\": 0.298, \"shots\": null, \"metric\": \"accuracy\", \"dataset\": \"slug:personqa\", \"benchmark\": \"PersonQA\", \"score_text\": null, \"source_url\": \"https://arxiv.org/abs/2508.10925\", \"reported_at\": \"2025-08-05\", \"baseline_model\": null, \"baseline_score\": null, \"evaluator_model\": null, \"configuration_notes\": \"Without web browsing.\"}, {\"score\": 0.87, \"shots\": null, \"metric\": \"accuracy\", \"dataset\": \"slug:bbq\", \"benchmark\": \"BBQ\", \"score_text\": null, \"source_url\": \"https://arxiv.org/abs/2508.10925\", \"reported_at\": \"2025-08-05\", \"baseline_model\": null, \"baseline_score\": null, \"evaluator_model\": null, \"configuration_notes\": \"Ambiguous questions.\"}, {\"score\": 0.9, \"shots\": null, \"metric\": \"accuracy\", \"dataset\": \"slug:bbq\", \"benchmark\": \"BBQ\", \"score_text\": null, \"source_url\": \"https://arxiv.org/abs/2508.10925\", \"reported_at\": \"2025-08-05\", \"baseline_model\": null, \"baseline_score\": null, \"evaluator_model\": null, \"configuration_notes\": \"Disambiguated questions.\"}], \"safety_ethics\": {\"mitigation\": [{\"source_url\": \"https://cdn.openai.com/pdf/419b6906-9da6-406c-a19d-1bb078ac7637/oai_gpt-oss_model_card.pdf\", \"description\": \"Pretraining data was filtered for harmful content, especially hazardous CBRN-related content, using CBRN filters from GPT-4o.\"}, {\"source_url\": \"https://cdn.openai.com/pdf/419b6906-9da6-406c-a19d-1bb078ac7637/oai_gpt-oss_model_card.pdf\", \"description\": \"Post-training used deliberative alignment and instruction hierarchy training to encourage refusal of unsafe prompts and resistance to prompt injection.\"}, {\"source_url\": \"https://openai.com/index/gpt-oss-model-card/\", \"description\": \"OpenAI recommends additional downstream safeguards, filtering, moderation, monitoring, or summarization, especially before exposing chain-of-thought to users.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"Deliberative alignment was used during post-training to teach refusal behavior and robustness to jailbreaks.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"The instruction hierarchy was used to resolve instruction conflicts and defend against prompt injection.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"OpenAI conducted scalable Preparedness evaluations and adversarial fine-tuning tests for biological, chemical, cyber, and AI self-improvement risks.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"The model card recommends downstream filtering, moderation, or summarization before exposing chain-of-thought content to users.\"}], \"safety_risk\": [{\"source_url\": \"https://openai.com/index/gpt-oss-model-card/\", \"description\": \"Open-weight release removes OpenAI\'s ability to revoke access or apply additional centralized mitigations after release; determined actors may fine-tune the model to bypass safety refusals or increase harmful capabilities.\"}, {\"source_url\": \"https://cdn.openai.com/pdf/419b6906-9da6-406c-a19d-1bb078ac7637/oai_gpt-oss_model_card.pdf\", \"description\": \"The model can hallucinate factual answers and chain-of-thought content; reported SimpleQA and PersonQA results were weaker than OpenAI o4-mini.\"}, {\"source_url\": \"https://cdn.openai.com/pdf/419b6906-9da6-406c-a19d-1bb078ac7637/oai_gpt-oss_model_card.pdf\", \"description\": \"The model generally performs below OpenAI o4-mini on instruction-hierarchy evaluations, including system-prompt extraction and prompt-injection hijacking.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"Open-weight users may fine-tune the model to bypass safety refusals or optimize harmful capabilities.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"The model\'s health outputs should not be treated as professional diagnosis or treatment advice.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"The open-weight release creates a risk that downstream modifications alter the model\'s safety and capability profile.\"}], \"risk_summary\": \"The model includes safety training and filtering, but its open weights can be modified to bypass refusals or increase harmful capabilities, so downstream deployers must add safeguards and monitoring.\", \"prohibited_use\": [{\"source_url\": \"https://raw.githubusercontent.com/openai/gpt-oss/main/USAGE_POLICY\", \"description\": \"Use that violates applicable law is prohibited by the OpenAI gpt-oss usage policy.\"}, {\"source_url\": \"https://github.com/openai/gpt-oss/blob/main/USAGE_POLICY\", \"description\": \"Users must comply with all applicable law when using gpt-oss-120b and gpt-oss-20b.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"The model is not intended to provide medical diagnosis or treatment.\"}], \"ethical_considerations\": [{\"source_url\": \"https://cdn.openai.com/pdf/419b6906-9da6-406c-a19d-1bb078ac7637/oai_gpt-oss_model_card.pdf\", \"description\": \"The model was evaluated for fairness and bias with BBQ; the model card reports approximate parity with OpenAI o4-mini but does not establish absence of subgroup harms.\"}, {\"source_url\": \"https://openai.com/index/gpt-oss-model-card/\", \"description\": \"Downstream developers and deployers retain responsibility for system-level safety decisions when integrating the open-weight model.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"Developers and enterprises may need safeguards beyond the model\'s default behavior to replicate system-level protections of hosted models.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"Chains of thought should not be shown directly to end users without additional filtering, moderation, or summarization.\"}, {\"source_url\": \"https://arxiv.org/abs/2508.10925\", \"description\": \"The model was evaluated for fairness and bias using BBQ, with separate ambiguous and disambiguated-question results.\"}]}, \"license_policy\": [{\"kind\": \"declared\", \"license\": \"Apache License 2.0\", \"spdx_id\": \"Apache-2.0\", \"scope_note\": \"Apache License 2.0 governs the released model weights and associated released artifacts; the separate OpenAI gpt-oss Usage Policy also applies.\", \"source_url\": \"https://huggingface.co/openai/gpt-oss-120b/blob/main/LICENSE\", \"license_uri\": \"https://raw.githubusercontent.com/openai/gpt-oss/main/LICENSE\", \"restrictions\": [\"Redistributions must include a copy of the Apache License 2.0.\", \"Modified files must carry prominent notices stating that they were changed.\", \"Applicable copyright, patent, trademark, attribution, and notice requirements must be retained as specified by Apache License 2.0.\", \"Users must comply with applicable law under the OpenAI gpt-oss Usage Policy.\"], \"usage_policy\": \"OpenAI gpt-oss Usage Policy\", \"commercial_use\": \"allowed\", \"usage_policy_uri\": \"https://raw.githubusercontent.com/openai/gpt-oss/main/USAGE_POLICY\"}, {\"kind\": \"declared\", \"license\": \"gpt-oss usage policy\", \"spdx_id\": null, \"scope_note\": \"Separate usage-policy document accompanying the Apache 2.0 license.\", \"source_url\": \"https://github.com/openai/gpt-oss/blob/main/USAGE_POLICY\", \"license_uri\": null, \"restrictions\": [\"Users must comply with all applicable law.\"], \"usage_policy\": \"gpt-oss usage policy\", \"commercial_use\": \"allowed\", \"usage_policy_uri\": \"https://github.com/openai/gpt-oss/blob/main/USAGE_POLICY\"}], \"transformation\": {\"notes\": \"The paper reports broad training categories and methods but does not disclose the full dataset composition, teacher identities, reward-model details, or complete optimization schedule.\", \"inputs\": [], \"method\": [\"pretraining\", \"large-scale distillation\", \"CoT reinforcement learning\", \"variable-effort reasoning training\", \"agentic tool-use training\", \"deliberative alignment\"], \"datasets\": [{\"role\": \"pretraining\", \"dataset\": \"slug:gpt-oss-pretraining-corpus\"}, {\"role\": \"distillation\", \"dataset\": \"slug:gpt-oss-distillation-data\"}, {\"role\": \"preference\", \"dataset\": \"slug:gpt-oss-post-training-problem-mixture\"}], \"objective\": \"Train an open-weight reasoning model with strong mathematical, coding, factual, health, and agentic tool-use capabilities while aligning behavior with OpenAI safety policies and supporting configurable reasoning effort.\", \"timestamp\": \"2025-08-05\", \"evidence_urls\": [\"https://arxiv.org/abs/2508.10925\", \"https://cdn.openai.com/pdf/419b6906-9da6-406c-a19d-1bb078ac7637/oai_gpt-oss_model_card.pdf\"], \"hyperparameters\": [{\"name\": \"pretraining_compute\", \"value\": \"2.1 million H100-hours for gpt-oss-120b\"}, {\"name\": \"reasoning_levels\", \"value\": \"low, medium, high\"}, {\"name\": \"context_length\", \"value\": \"131,072 tokens\"}, {\"name\": \"active_parameters_per_token\", \"value\": \"5.13B\"}, {\"name\": \"experts\", \"value\": \"128 total experts; top-4 experts active per token\"}, {\"name\": \"attention_pattern\", \"value\": \"Alternating locally banded and dense attention; bandwidth 128 tokens\"}, {\"name\": \"quantization\", \"value\": \"MXFP4 at 4.25 bits per parameter for MoE weights\"}]}}, \"aibomSummary\": {\"datasets\": 25, \"licenses\": 2, \"references\": 23, \"evaluations\": 26, \"method_steps\": 6, \"safety_items\": 21, \"transformation_inputs\": 0}, \"areaDecisions\": [{\"area\": \"model\", \"chosen\": \"huggingface\", \"rationale\": \"저장소 설정과 모델 카드가 구성 및 아티팩트 사실을 더 직접적으로 제공한다.\"}, {\"area\": \"provenance\", \"chosen\": \"huggingface\", \"rationale\": \"두 입력의 계보가 일치하며 Hugging Face 설명이 공개 부모 부재를 명확히 기록한다.\"}, {\"area\": \"transformation\", \"chosen\": \"paper\", \"rationale\": \"논문이 변환 방법, 목적, 하이퍼파라미터와 학습 데이터 역할을 더 상세히 제시한다.\"}, {\"area\": \"datasets\", \"chosen\": \"combined\", \"rationale\": \"두 입력의 데이터셋 항목을 식별자별로 합쳤다.\"}, {\"area\": \"evaluations\", \"chosen\": \"combined\", \"rationale\": \"두 출처의 평가 행을 원문 수치 그대로 합쳤다.\"}, {\"area\": \"safety_ethics\", \"chosen\": \"combined\", \"rationale\": \"두 입력의 안전 및 윤리 항목을 중복 제거 후 합쳤다.\"}, {\"area\": \"license_policy\", \"chosen\": \"huggingface\", \"rationale\": \"저장소 라이선스 파일과 정책 파일을 우선하고 논문의 별도 정책 항목을 보완했다.\"}, {\"area\": \"references\", \"chosen\": \"combined\", \"rationale\": \"두 입력에서 열린 모든 문서를 URI별로 합쳤다.\"}], \"fieldDecisions\": [{\"field\": \"modelId\", \"chosen\": \"huggingface\", \"rationale\": \"Hugging Face 저장소가 요청된 정확한 모델 식별자를 확인한다.\"}, {\"field\": \"namespace\", \"chosen\": \"huggingface\", \"rationale\": \"저장소 경로의 네임스페이스가 명시되어 있다.\"}, {\"field\": \"modelName\", \"chosen\": \"huggingface\", \"rationale\": \"저장소 경로의 모델명이 명시되어 있다.\"}, {\"field\": \"familyKey\", \"chosen\": \"combined\", \"rationale\": \"두 입력이 동일한 새 gptoss 가족 키에 동의한다.\"}, {\"field\": \"familyName\", \"chosen\": \"paper\", \"rationale\": \"논문 입력이 가족명을 명시적으로 확인하며 Hugging Face와 일치한다.\"}, {\"field\": \"modelRole\", \"chosen\": \"combined\", \"rationale\": \"두 입력이 동일한 계열 대표 BASE 분류를 제시한다.\"}, {\"field\": \"supplier\", \"chosen\": \"huggingface\", \"rationale\": \"정확한 저장소의 공급자가 명시되어 있다.\"}, {\"field\": \"familyDeveloper\", \"chosen\": \"paper\", \"rationale\": \"공식 기술 문서가 가족 개발자를 명시적으로 확인한다.\"}, {\"field\": \"familyReleaseDate\", \"chosen\": \"paper\", \"rationale\": \"공식 모델 문서의 공개일을 사용한다.\"}, {\"field\": \"familyLicenseName\", \"chosen\": \"paper\", \"rationale\": \"공식 문서가 가족 라이선스를 명시적으로 확인한다.\"}, {\"field\": \"primaryPurpose\", \"chosen\": \"huggingface\", \"rationale\": \"저장소의 파이프라인 목적을 우선한다.\"}, {\"field\": \"modelVersion\", \"chosen\": \"huggingface\", \"rationale\": \"저장소 main 커밋의 짧은 SHA가 명시되어 있다.\"}, {\"field\": \"packageUrl\", \"chosen\": \"huggingface\", \"rationale\": \"커밋 버전에 기반한 저장소 패키지 URL이 명시되어 있다.\"}, {\"field\": \"modelUrl\", \"chosen\": \"huggingface\", \"rationale\": \"정확한 모델 저장소 URL을 우선한다.\"}, {\"field\": \"description\", \"chosen\": \"combined\", \"rationale\": \"두 설명을 결합해 공식 모델과 논문 식별자를 함께 명시한다.\"}], \"parentCandidates\": []}','2026-09-28 03:19:10.062019');
