t_card','https://huggingface.co/datasets/gorilla-llm/Berkeley-Function-Calling-Leaderboard','61fc0608cfd831fcfbbaa676ebdfef0ed963eeda','2026-09-26','f022f733d2cefce78112f4c90be651dc8968642fdb29609551d29d240dfd4cb6','{\"title\": \"gorilla-llm/Berkeley-Function-Calling-Leaderboard dataset card\", \"http_status\": 200, \"published_at\": \"2026-04-29\"}'),(646,'dataset_card','https://huggingface.co/datasets/gorilla-llm/APIBench','ac21e1892e634dfa25f8ad75f16cbdbfb0a5736d','2026-09-26','efd000c47fcea35206be55ee2a6a7b8aec28318befff40f158665c41bceb52d1','{\"title\": \"gorilla-llm/APIBench dataset card\", \"http_status\": 200, \"published_at\": \"2023-05-29\"}'),(647,'repository','https://github.com/nexusflowai/NexusRaven','f32882763bb3e220722883821919c14abdd3d156','2026-09-26','7c99955c12c863ca033091ada990b932e28d3c6f591defba17cfd7f0f154cff6','{\"title\": \"nexusflowai/NexusRaven (evaluation code and data license notes)\", \"http_status\": 200, \"published_at\": \"2023-09-29\"}'),(648,'paper','https://arxiv.org/abs/2405.20947','v2','2026-09-26','1d7758238be44f4468c9e008f52fd509eef79e21bc4a109ea9efd99fe2735425','{\"title\": \"OR-Bench: An Over-Refusal Benchmark for Large Language Models\", \"http_status\": 200, \"published_at\": \"2026-08-24\"}'),(649,'dataset_card','https://huggingface.co/datasets/yahma/alpaca-cleaned','12567cabf869d7c92e573c7c783905fc160e9639','2026-09-26','6d7e1522b61784416fcd06c14c04d24e8204be4107f11d13d1c1343566f89b34','{\"title\": \"yahma/alpaca-cleaned dataset card\", \"http_status\": 200, \"published_at\": \"2023-04-10\"}'),(650,'repository','https://github.com/facebookresearch/Meta_SecAlign/blob/main/utils.py','2031502bdf5a046b437ec835c6b05ff468aa0699','2026-09-26','681c97640023ca291321d108698c6997c8191f63baf0113fd63a6fd99cb5c01b','{\"title\": \"facebookresearch/Meta_SecAlign - secalign_plus_plus.py / utils.py (generate_preference_dataset, instruct_dataset=\'alpaca\', self_generated_response=True)\", \"http_status\": 200, \"published_at\": \"2026-02-25\"}');
