/*!40000 ALTER TABLE `safety_ethics` DISABLE KEYS */;
INSERT INTO `safety_ethics` VALUES ('FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp','[{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"description\": \"Still vulnerable to strong adaptive/white-box attacks (e.g. GCG suffix optimization, embedding-based fake-delimiter escape attacks), per Table 6 of the Meta SecAlign paper.\"}, {\"reference\": \"https://huggingface.co/FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp\", \"description\": \"This is a community reproduction of the SecAlign++ recipe rather than the official facebook/Meta-SecAlign-8B checkpoint; no independent security evaluation specific to this adapter (LoRA r=32) has been published.\"}]',NULL,'[{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"description\": \"Not designed to defend against jailbreaks (malicious user) or direct prompt injection; the threat model assumes a benign user/system and a malicious environment/data source only.\"}]','[{\"reference\": \"https://arxiv.org/abs/2507.02735\", \"description\": \"Security/utility trade-off can be tuned at inference time by scaling the LoRA alpha parameter without retraining.\"}, {\"reference\": \"https://arxiv.org/abs/2507.02735\", \"description\": \"Must be used with the exact SecAlign++ chat template (added \'input\' message role, recursive delimiter filtering) for the defense to take effect.\"}]','{\"risk_summary\": \"Reduces attack success rate for indirect prompt injection on standard and several adaptive benchmarks by one to two orders of magnitude relative to the undefended base model, but remains vulnerable to strong adaptive attacks and does not address jailbreaks or direct prompt injection; independent evaluation of this specific third-party adapter (as opposed to the official Meta-SecAlign-8B checkpoint) is not published.\"}'),('FreedomIntelligence/HuatuoGPT-o1-8B','[{\"reference\": \"https://arxiv.org/abs/2412.18925\", \"description\": \"Model may produce hallucinated or medically inaccurate content despite its reasoning/self-correction design.\"}]','[{\"reference\": \"https://arxiv.org/abs/2412.18925\", \"description\": \"Users are asked to adhere to usage restrictions to safeguard the safety and integrity of downstream applications.\"}]','[{\"reference\": \"https://arxiv.org/abs/2412.18925\", \"description\": \"Not permitted for use in clinical or other industry applications where inaccuracies could lead to unintended consequences; authors state the model \'is not suitable for real-world applications\'.\"}]','[{\"reference\": \"https://arxiv.org/abs/2412.18925\", \"description\": \"Training data verifier (GPT-4o) reliability was manually audited on 200 sampled scoring instances, showing 96.5% accuracy in Stage 1 and 94.5% in Stage 2, to bound noise introduced by automated verification.\"}]','{\"risk_summary\": \"Paper\'s own Ethical Statement: the model may still produce hallucinations or inaccuracies and is explicitly not permitted for use in clinical or other industry applications where such inaccuracies could lead to unintended consequences.\"}'),('HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO','[{\"reference\": \"https://huggingface.co/HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO\", \"description\": \"MMLU accuracy decreased from 0.331 (baseline Qwen2.5-7B-Instruct) to 0.296 after DPO safety tuning.\"}, {\"reference\": \"https://huggingface.co/HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO\", \"description\": \"Refusal rate on OR-Bench 80K increased from 0.021 to 0.029, i.e. a modest rise in over-refusal of benign prompts.\"}]','[{\"reference\": \"https://huggingface.co/datasets/HPAI-BSC/Egida\", \"description\": \"The underlying Egida dataset contains real unsafe/jailbreak-eliciting prompts (and, in Egida-HSafe, human-annotated unsafe completions), collected and released specifically for safety research and retrofitting rather than misuse.\"}]','[{\"reference\": \"https://arxiv.org/abs/2502.13603\", \"description\": \"Paper explicitly frames the method and released artifacts as being for defensive safety research (reducing jailbreak susceptibility), not for producing or amplifying jailbreaks.\"}]','[{\"reference\": \"https://huggingface.co/HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO\", \"description\": \"DPO training on the Egida-DPO-Qwen2.5-7B-Instruct preference dataset lowers ASR on the Egida test split, DELPHI, Alert-Base, and Alert-Adv jailbreak benchmarks relative to the untuned base model.\"}]','{\"risk_summary\": \"DPO safety retrofitting reduces measured jailbreak Attack Success Ratio versus the Qwen2.5-7B-Instruct baseline across four benchmarks (roughly 10-45% relative reduction), while general capability (OpenLLM average) is reported stable; a small MMLU regression and a modest increase in benign-prompt refusal rate are observed trade-offs.\"}'),('HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge','[{\"reference\": \"https://huggingface.co/HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge\", \"description\": \"Judge performance varies across languages (weaker on culturally specific and time-dependent questions than universal-knowledge questions).\"}, {\"reference\": \"https://huggingface.co/datasets/HiTZ/truthful_judge\", \"description\": \"Inherits Anglocentric framing and imitative-falsehood biases from the original TruthfulQA benchmark.\"}]',NULL,'[{\"reference\": \"https://huggingface.co/HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge\", \"description\": \"Not for general-purpose creative text/dialogue generation, providing direct factual information, safety-critical use without validation, or building systems intended to deceive or spread misinformation.\"}]','[{\"reference\": \"https://huggingface.co/HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge\", \"description\": \"Recommend cross-verification with human oversight for critical applications.\"}]','{\"risk_summary\": \"Low-to-moderate: a text-judgment tool, not a generative assistant; main risks are language-uneven judgment quality and inherited TruthfulQA/base-model biases.\"}'),('NousResearch/Hermes-3-Llama-3.1-8B','[{\"reference\": \"https://arxiv.org/abs/2408.11857\", \"description\": \"High system-prompt sensitivity means safety behavior can vary substantially depending on how a deployer configures the persona/system prompt.\"}]','[{\"reference\": \"https://arxiv.org/abs/2408.11857\", \"description\": \"Hermes is designed to follow system and instruction prompts \'exactly and neutrally\' and is distinguished from closed models that refuse instructions on moral grounds; the authors state \'there is no such thing as latent thoughtcrime\' for Hermes.\"}]','[{\"reference\": \"https://github.com/meta-llama/llama-models/blob/main/models/llama3_1/LICENSE\", \"description\": \"Use is subject to the inherited Llama 3.1 Acceptable Use Policy, which prohibits illegal activity, child sexual exploitation material, weapons development (CBRNE), and other listed harmful uses.\"}]','[{\"reference\": \"https://arxiv.org/abs/2408.11857\", \"description\": \"The authors argue appropriate guardrails and active intervention should be implemented at the surrounding system/application level rather than baked into the model.\"}]','{\"risk_summary\": \"Neutrally-aligned model: fewer built-in moral refusals by design, with the paper explicitly stating guardrails are intended to be implemented at the system/application level rather than in the model itself.\"}'),('mellee030/MedQwen-7B-LoRA','[{\"reference\": \"https://huggingface.co/mellee030/MedQwen-7B-LoRA\", \"description\": \"Performance may vary on medical topics underrepresented in the training data.\"}, {\"reference\": \"https://huggingface.co/mellee030/MedQwen-7B-LoRA\", \"description\": \"Evaluated on a specific Chinese medical Q&A corpus (undisclosed source/composition); results may differ on other datasets or domains.\"}, {\"reference\": \"https://huggingface.co/mellee030/MedQwen-7B-LoRA\", \"description\": \"Intended for Chinese medical Q&A only; behavior outside this domain/language is not characterized.\"}]',NULL,'[{\"reference\": \"https://huggingface.co/mellee030/MedQwen-7B-LoRA\", \"description\": \"Not a substitute for professional medical advice.\"}]',NULL,'{\"risk_summary\": \"Low-scope community domain adapter; card explicitly disclaims clinical use and provides no formal safety evaluation.\"}'),('meta-llama/Llama-3.1-8B','[{\"reference\": \"https://raw.githubusercontent.com/meta-llama/llama-models/main/models/llama3_1/MODEL_CARD.md\", \"description\": \"As a pretrained-only checkpoint (no instruction/safety tuning), outputs may be inaccurate, biased, unsafe or objectionable if used directly in user-facing applications.\"}]',NULL,'[{\"reference\": \"https://github.com/meta-llama/llama-models/blob/main/models/llama3_1/USE_POLICY.md\", \"description\": \"Use must comply with the Llama 3.1 Acceptable Use Policy, which prohibits illegal activity, generation of CSAM, weapons development (incl. CBRNE), and other listed disallowed uses.\"}]','[{\"reference\": \"https://raw.githubusercontent.com/meta-llama/llama-models/main/models/llama3_1/MODEL_CARD.md\", \"description\": \"Meta recommends deploying system-level safeguards (e.g., Llama Guard 3, Prompt Guard, Code Shield) around Llama Materials in production/agentic use.\"}]','{\"risk_summary\": \"Meta describes a multi-faceted safety process (data curation, red-teaming for CBRNE/child-safety/cyber-risk, refusal-tone tuning) applied across the Llama 3.1 family; the base model itself carries a broad disclaimer of warranty and liability and is not safety fine-tuned (no RLHF/DPO alignment applied to this checkpoint).\"}'),('meta-llama/Llama-3.1-8B-Instruct','[{\"reference\": \"https://raw.githubusercontent.com/meta-llama/llama-models/main/models/llama3_1/MODEL_CARD.md\", \"description\": \"Model may still produce inaccurate, biased, or unsafe outputs; downstream deployers are responsible for additional testing and tuning before high-stakes or production use.\"}]','[{\"reference\": \"https://raw.githubusercontent.com/meta-llama/llama-models/main/models/llama3_1/MODEL_CARD.md\", \"description\": \"Red-teaming exercises specifically targeted critical risk areas: CBRNE (chemical, biological, radiological, nuclear, and high-yield explosives) materials, child safety, and cyber attack enablement.\"}]','[{\"reference\": \"https://github.com/meta-llama/llama-models/blob/main/models/llama3_1/USE_POLICY.md\", \"description\": \"Use must comply with the Llama 3.1 Acceptable Use Policy, which prohibits illegal activity, CSAM generation, weapons/CBRNE development, and other listed disallowed uses.\"}]','[{\"reference\": \"https://raw.githubusercontent.com/meta-llama/llama-models/main/models/llama3_1/MODEL_CARD.md\", \"description\": \"Multi-round SFT + rejection sampling + DPO with refusal-tone and safety/borderline data; recommendation to layer system-level safeguards (Llama Guard 3, Prompt Guard, Code Shield) for agentic or user-facing deployments.\"}]','{\"risk_summary\": \"Meta applies a multi-faceted safety pipeline for the instruction-tuned models: data curation combining human-generated and synthetic safety data, LLM-based classifiers to select high-quality prompts/responses, refusal-tone tuning, and red-teaming by cybersecurity/adversarial-ML/responsible-AI/integrity experts, focused on CBRNE, child safety, and cyber-attack-enablement risks.\"}'),('mlx-community/Meta-Llama-3.1-8B-Instruct-bf16','[{\"reference\": \"https://huggingface.co/mlx-community/Meta-Llama-3.1-8B-Instruct-bf16\", \"description\": \"As a format conversion, this artifact carries the same general LLM risks as the source model (hallucination, bias, unsafe or inaccurate outputs) with no additional mitigation applied during conversion.\"}]',NULL,'[{\"reference\": \"https://www.llama.com/llama3_1/use-policy/\", \"description\": \"Use is governed by the Llama 3.1 Acceptable Use Policy (inherited from the source model), which prohibits illegal activity, weapons/CBRNE development, generation of CSAM, disinformation, unauthorized professional advice, and other harmful uses.\"}]',NULL,'{\"risk_summary\": \"Inherited from Llama 3.1 8B Instruct; the MLX conversion reports no independent safety evaluation or new risk-mitigation work.\"}'),('mlx-community/Qwen2.5-7B-Instruct-bf16','[{\"reference\": \"https://huggingface.co/mlx-community/Qwen2.5-7B-Instruct-bf16\", \"description\": \"As a format conversion, this artifact carries the same general LLM risks as the source model (hallucination, bias, unsafe or inaccurate outputs) with no additional mitigation applied during conversion.\"}]',NULL,NULL,NULL,'{\"risk_summary\": \"Inherited from Qwen2.5-7B-Instruct; the MLX conversion reports no independent safety evaluation or new risk-mitigation work.\"}');
/*!40000 ALTER TABLE `safety_ethics` ENABLE KEYS */;
UNLOCK TABLES;

