INSERT INTO `transformation` VALUES (79,'[{\"role\": \"base\", \"model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"external\": false}, {\"role\": \"generator\", \"model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"external\": false}]','FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp','[\"instruction tuning (inherited base)\", \"direct preference optimization (DPO) via the SecAlign++ recipe\", \"LoRA adapter fine-tuning\"]','Teach the base instruction-tuned model to ignore prompt injections embedded in untrusted data (placed in a new \'input\' chat-template role) while preserving instruction-following and agentic utility, using randomized injection position and self-generated preference responses (SecAlign++ improvements over the original SecAlign recipe).','{\"epochs\": 3, \"lora_r\": 32, \"adapter\": {\"r\": 32, \"dtype\": \"bfloat16\", \"library\": \"peft\", \"peft_type\": \"LORA\", \"base_model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"lora_alpha\": 8, \"target_modules\": [\"q_proj\", \"v_proj\", \"gate_proj\", \"down_proj\", \"up_proj\"]}, \"dpo_beta\": 0.1, \"dpo_loss\": \"sigmoid\", \"batch_size\": 1, \"lora_alpha\": 8, \"learning_rate\": 0.00016, \"target_modules\": [\"q_proj\", \"v_proj\", \"gate_proj\", \"up_proj\", \"down_proj\"], \"gradient_accumulation_steps\": 16}','[{\"role\": \"preference\", \"dataset\": \"slug:synthetic_alpaca\"}]','2026-03-02','{\"notes\": \"Card-reported hyperparameters (3 epochs, DPO beta=0.1, batch size 1, grad accumulation 16, lr=1.6e-4) match exactly the META-SECALIGN-8B recipe described in arXiv:2507.02735 Sec 4.1. However, that paper specifies LoRA r=64 for the official 8B model, while this adapter\'s adapter_config.json uses r=32 (the paper\'s 70B rank), and lora_dropout is not present in the adapter_config.json (paper recipe uses 0.1) — indicating this is an independent reproduction rather than a byte-identical copy of the official checkpoint.\", \"evidence\": [\"https://huggingface.co/FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp\", \"https://huggingface.co/FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp/raw/main/adapter_config.json\", \"https://arxiv.org/abs/2507.02735\"]}'),(81,'[{\"role\": \"base\", \"model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"external\": false}]','HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge','[\"supervised fine-tuning (judge task: predict Yes/No truthfulness label)\"]','Turn a general-purpose instruction-tuned LLM into an automatic LLM-as-a-Judge that scores truthfulness of QA answers consistently across English, Basque, Catalan, Galician and Spanish, as a more reliable alternative to multiple-choice truthfulness metrics.','{\"epochs\": 5, \"precision\": \"bfloat16 mixed precision\", \"learning_rate\": 0.01}','[{\"role\": \"finetuning\", \"dataset\": \"HiTZ/truthful_judge\"}]','2025-05-27','{\"notes\": \"Model card states batch size and optimizer are \'refer to project code\' (https://github.com/hitz-zentroa/truthfulqa-multi, judge/train_judge/); these were not documented in the README or found in the fetched repo excerpt.\", \"evidence\": [\"https://huggingface.co/HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge\", \"https://arxiv.org/abs/2502.09387\"]}'),(82,'[{\"role\": \"base\", \"model\": \"Qwen/Qwen2.5-7B-Instruct\", \"external\": false}]','HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO','[\"Direct Preference Optimization (DPO) safety retrofitting\"]','Reduce the jailbreak attack success rate (ASR) of Qwen2.5-7B-Instruct against adversarial/jailbreak prompts while preserving general instruction-following capability, using an efficient, low-compute DPO recipe.','{\"method\": \"DPO\", \"hardware\": \"4x NVIDIA H100 64GB GPUs (1 node), small-model training tier\", \"framework\": \"OpenRLHF v0.3.2\", \"batch_size\": 8, \"learning_rate\": 0.0000001, \"training_time\": \"1.59 hours (reported as single-H100-equivalent compute time; small-model tier ranges 7.57 minutes-1.59 hours across models)\"}','[{\"role\": \"preference\", \"dataset\": \"slug:egida-dpo-qwen2.5-7b-instruct\"}]','2025-02-18','{\"notes\": \"Paper states small models (including Qwen2.5-7B-Instruct) were trained on 4 GPUs at batch size 8 and lr=1e-7, versus large models (64 GPUs, batch size 64, lr=1e-6). DPO beta value, epoch count, and whether full-parameter or PEFT tuning was used are not stated; released safetensors total 7.6B parameters matching a full fine-tune of the base model size.\", \"evidence\": [\"https://huggingface.co/HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO\", \"https://arxiv.org/abs/2502.13603\"]}'),(83,'[{\"role\": \"base\", \"model\": \"Qwen/Qwen2.5-7B-Instruct\", \"external\": false}]','mellee030/MedQwen-7B-LoRA','[\"LoRA PEFT fine-tuning\"]','Adapt Qwen2.5-7B-Instruct to Chinese medical question answering / dialogue while keeping the adapter lightweight and the base model\'s general capabilities intact.','{\"epochs\": 3, \"adapter\": {\"r\": 8, \"bias\": \"none\", \"use_dora\": false, \"peft_type\": \"LORA\", \"task_type\": \"CAUSAL_LM\", \"lora_alpha\": 16, \"use_rslora\": false, \"lora_dropout\": 0.05, \"peft_version\": \"0.19.1\", \"target_modules\": [\"down_proj\", \"k_proj\", \"up_proj\", \"o_proj\", \"v_proj\", \"q_proj\", \"gate_proj\"], \"base_model_name_or_path\": \"/home/yuxincui/MedQwen/Qwen2.5-7B-Instruct\"}, \"lora_rank\": 8, \"precision\": \"FP16\", \"batch_size\": 1, \"lora_alpha\": 16, \"lora_dropout\": 0.05, \"lr_scheduler\": \"cosine with warmup\", \"learning_rate\": 0.0002, \"target_modules\": [\"q_proj\", \"k_proj\", \"v_proj\", \"o_proj\", \"gate_proj\", \"up_proj\", \"down_proj\"], \"max_sequence_length\": 256, \"effective_batch_size\": 8, \"trainable_params_share\": \"~1% of base model parameters (per HF card)\", \"gradient_accumulation_steps\": 8}','[{\"role\": \"finetuning\", \"dataset\": \"slug:medqwen-7b-lora-chinese-medical-dialogue-30284\"}]',NULL,'{\"notes\": \"Trained on a single GCP L4 GPU (24GB VRAM); training time ~12 hours per HF card. HF repo was created 2026-04-17 and last modified 2026-04-18, used only as a rough proxy for release timing since no explicit training/release date is stated.\", \"evidence\": [\"https://huggingface.co/mellee030/MedQwen-7B-LoRA\", \"https://huggingface.co/mellee030/MedQwen-7B-LoRA/raw/main/adapter_config.json\"]}'),(84,'[{\"role\": \"base\", \"model\": \"meta-llama/Llama-3.1-8B\", \"external\": false}]','meta-llama/Llama-3.1-8B-Instruct','[\"supervised fine-tuning\", \"rejection sampling\", \"direct preference optimization\", \"model averaging\"]','Align the pretrained Llama 3.1 8B base model to follow instructions, hold multi-turn dialogue, use tools, and improve helpfulness/safety, producing a chat-ready assistant model.',NULL,'[{\"role\": \"finetuning\", \"dataset\": \"slug:llama-3.1-post-training-data\"}, {\"role\": \"preference\", \"dataset\": \"slug:llama-3.1-post-training-data\"}]','2024-07-23','{\"notes\": \"Meta describes several rounds of SFT, rejection sampling, and DPO on top of human-annotated, rejection-sampled, and synthetic/model-generated data, with model averaging across checkpoints; exact hyperparameters, number of rounds, and full dataset provenance for the 8B-specific run are not disclosed in the sources reviewed.\", \"evidence\": [\"https://huggingface.co/api/models/meta-llama/Llama-3.1-8B-Instruct\", \"https://raw.githubusercontent.com/meta-llama/llama-models/main/models/llama3_1/MODEL_CARD.md\"]}'),(85,NULL,'meta-llama/Llama-3.1-8B','[\"pretraining\", \"long-context continued pre-training\", \"annealing on selected high-quality data\"]','Train a dense decoder-only Transformer foundation model on a large multilingual/code/math text corpus for general-purpose next-token prediction, later extended to 128K context via continued pretraining.',NULL,'[{\"role\": \"pretraining\", \"dataset\": \"slug:llama-3.1-pretraining-mixture\"}]','2024-07-23','{\"notes\": \"Exact compute budget, optimizer settings, and full dataset mixture ratios are not disclosed in the model card or paper excerpt reviewed; the paper (arXiv 2407.21783) describes methodology at a high level (data curation, scaling laws, infrastructure) without a fully itemized dataset list.\", \"evidence\": [\"https://raw.githubusercontent.com/meta-llama/llama-models/main/models/llama3_1/MODEL_CARD.md\", \"https://arxiv.org/abs/2407.21783\"]}'),(86,'[{\"role\": \"base\", \"model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"external\": false}]','mlx-community/Meta-Llama-3.1-8B-Instruct-bf16','[\"format conversion (MLX)\"]','Repackage the BF16 safetensors weights of meta-llama/Llama-3.1-8B-Instruct into Apple\'s MLX array/model format so the model can be loaded and run locally with mlx-lm on Apple silicon.',NULL,NULL,'2024-07-23','{\"notes\": \"Conversion tool: mlx-lm 0.19.0 (per model card). No training data was used; this is a lossless-precision format/runtime conversion (BF16 -> BF16 MLX arrays), not a quantization or fine-tune. Exact conversion command/flags and numerical-equivalence tests are not published.\", \"evidence\": [\"https://huggingface.co/mlx-community/Meta-Llama-3.1-8B-Instruct-bf16\"]}'),(87,'[{\"role\": \"base\", \"model\": \"Qwen/Qwen2.5-7B-Instruct\", \"external\": false}]','mlx-community/Qwen2.5-7B-Instruct-bf16','[\"format conversion (MLX)\"]','Repackage the BF16 safetensors weights of Qwen/Qwen2.5-7B-Instruct into Apple\'s MLX array/model format so the model can be loaded and run locally with mlx-lm on Apple silicon.',NULL,NULL,'2024-09-18','{\"notes\": \"Conversion tool: mlx-lm 0.18.1 (per model card). No training data was used; this is a lossless-precision format/runtime conversion (BF16 -> BF16 MLX arrays), not a quantization or fine-tune. Exact conversion command/flags and numerical-equivalence tests are not published.\", \"evidence\": [\"https://huggingface.co/mlx-community/Qwen2.5-7B-Instruct-bf16\"]}'),(88,'[{\"role\": \"base\", \"model\": \"meta-llama/Llama-3.1-8B\", \"external\": false}]','NousResearch/Hermes-3-Llama-3.1-8B','[\"supervised fine-tuning\", \"direct preference optimization (LoRA)\"]','Turn the Llama 3.1 8B base (pretrained) model into a neutrally-aligned, highly steerable generalist instruct and tool-use assistant with strong reasoning, roleplaying, agentic, and structured-output capabilities.','{\"dpo\": {\"impact\": \"moderate but positive for the 8B model; SFT+DPO outscored SFT-only on GPT4All (72.30 vs 72.03), AGIEval (41.26 vs 40.17), TruthfulQA (58.69 vs 56.43), IFEval (66.70 vs 66.17), MT-Bench (8.27 vs 8.18), but slightly lower on Big Bench (43.04 vs 44.57)\", \"method\": \"LoRA adapter DPO (reference and policy model not both fully materialized)\", \"lora_rank\": 32, \"optimizer\": \"RMSProp\", \"lora_alpha\": 16, \"lr_schedule\": \"linear decay after 9 warmup steps\", \"lora_dropout\": 0.05, \"neftune_alpha\": 5, \"peak_learning_rate\": 0.000003, \"lora_target_modules\": \"all linear layers\"}, \"sft\": {\"compute\": \"48 GPUs (six HGX nodes of 8x H100 SXM5), batch size 48, 147 GPU-hours\", \"framework\": \"modified Axolotl (Flash Attention 2 variable-length packing) with PyTorch FSDP\", \"optimizer\": \"AdamW\", \"lr_schedule\": \"cosine decay with 300-step warmup\", \"loss_masking\": \"instruction and tool-output tokens set to ignore index (-100), loss computed only on response/tool-use tokens\", \"weight_decay\": 0.01, \"epochs_trained\": 4, \"selected_epoch\": 4, \"packing_efficiency\": \"96% (4% padding tokens)\", \"peak_learning_rate\": 0.000007, \"selection_criterion\": \"epoch checkpoint chosen via min-max normalized average of GPT4All benchmarks (ARC-Easy/Challenge, BoolQ, HellaSwag, OpenBookQA, PIQA, WinoGrande), AGIEval, IFEval, and MT-Bench\", \"target_sequence_length\": 8192}, \"adapter\": {\"dpo_phase\": {\"rank\": 32, \"type\": \"LoRA\", \"alpha\": 16, \"dropout\": 0.05, \"target_modules\": \"all linear layers\"}}}','[{\"role\": \"finetuning\", \"dataset\": \"slug:hermes-3-sft-mixture\"}, {\"role\": \"finetuning\", \"dataset\": \"NousResearch/hermes-function-calling-v1\"}, {\"role\": \"preference\", \"dataset\": \"slug:hermes-3-dpo-preference-data\"}]','2024-07-28','{\"notes\": \"Data curation for the Hermes 3 SFT mixture ran from March 2024 to August 2024. Training data construction combined existing sources (e.g. NousResearch/hermes-function-calling-v1) with domain-specific synthetic generation using Evol-Instruct-inspired schemes, followed by filtering (length thresholds, refusal removal, empty-turn removal, prioritizing strongest-model generations).\", \"evidence\": [\"https://arxiv.org/abs/2408.11857\", \"https://huggingface.co/NousResearch/Hermes-3-Llama-3.1-8B/raw/main/README.md\"]}'),(89,'[{\"role\": \"base\", \"model\": \"Qwen/Qwen2.5-7B\", \"external\": false}]','Qwen/Qwen2.5-7B-Instruct-1M','[\"progressive long-context pretraining (5 stages: 4K, 32K, 65536, 131072, 262144 tokens)\", \"RoPE base frequency adjustment (10,000 -> 10,000,000)\", \"long data synthesis (fill-in-the-middle, keyword/position-based retrieval, paragraph reordering)\", \"two-stage long-context supervised fine-tuning (short sequences up to 32K, then mixed short/long up to 262K)\", \"offline reinforcement learning on short (<=8K token) samples\", \"custom sparse-attention (dual chunk attention) inference-time length extrapolation for deployment\"]','Extend Qwen2.5-7B(-Instruct) from a 128K-token context window to a ~1M-token context window while preserving short-context instruction-following quality, using progressive pretraining, synthesized long-context data, staged SFT and RL.','{\"rl_max_len\": 8192, \"rope_theta_final\": 10000000, \"sft_stage1_max_len\": 32768, \"sft_stage2_max_len\": 262144, \"pretraining_stage_context_lengths\": [4096, 32768, 65536, 131072, 262144]}','[{\"role\": \"finetuning\", \"dataset\": \"slug:qwen2.5-1m-long-context-synthesis\"}]','2025-01-26','{\"notes\": \"Long-context training data mix used ~75% sequences at the current stage\'s maximum length and ~25% shorter sequences at each pretraining stage, per the technical report.\", \"evidence\": [\"https://arxiv.org/abs/2501.15383\", \"https://qwenlm.github.io/blog/qwen2.5-1m/\", \"https://huggingface.co/Qwen/Qwen2.5-7B-Instruct-1M/raw/main/README.md\"]}'),(90,'[{\"role\": \"base\", \"model\": \"Qwen/Qwen2.5-7B\", \"external\": false}]','Qwen/Qwen2.5-7B-Instruct','[\"supervised fine-tuning\", \"multistage reinforcement learning (offline and online preference optimization)\"]','Turn the Qwen2.5-7B base checkpoint into an instruction-following, chat-capable assistant with improved long-text generation, structured/JSON output reliability, and robustness to diverse system prompts.',NULL,'[{\"role\": \"finetuning\", \"dataset\": \"slug:qwen2.5-post-training-mixture\"}]','2024-09-19','{\"notes\": \"The technical report describes the post-training pipeline at a high level (>1M SFT samples, multistage RL) but does not disclose per-stage hyperparameters (learning rate, RL algorithm details, reward model) in the sections reviewed.\", \"evidence\": [\"https://huggingface.co/Qwen/Qwen2.5-7B-Instruct\", \"https://arxiv.org/abs/2412.15115\", \"https://qwenlm.github.io/blog/qwen2.5/\"]}'),(91,NULL,'Qwen/Qwen2.5-7B','[\"pretraining\"]','Train a dense decoder-only Transformer via autoregressive next-token prediction on a large-scale multilingual, code, and math corpus to serve as the foundation checkpoint for the Qwen2.5-7B lineage.',NULL,'[{\"role\": \"pretraining\", \"dataset\": \"slug:qwen2.5-pretraining-corpus\"}]','2024-09-19','{\"notes\": \"Exact optimizer settings, learning-rate schedule, and batch size are not disclosed in the model card, blog, or technical report abstract/tables reviewed.\", \"evidence\": [\"https://huggingface.co/Qwen/Qwen2.5-7B\", \"https://arxiv.org/abs/2412.15115\", \"https://qwenlm.github.io/blog/qwen2.5/\"]}'),(92,'[{\"role\": \"base\", \"model\": \"meta-llama/Llama-3.1-8B-Instruct\", \"external\": false}, {\"role\": \"generator\", \"model\": \"GPT-4o\", \"external\": true}, {\"role\": \"verifier\", \"model\": \"GPT-4o\", \"external\": true}]','FreedomIntelligence/HuatuoGPT-o1-8B','[\"supervised fine-tuning on synthesized complex chain-of-thought trajectories\", \"reinforcement learning with PPO using verifier-based sparse rewards\"]','Adapt the general-purpose instruction-tuned Llama-3.1-8B-Instruct model into a medical reasoning model that searches for and reflects on complex reasoning paths (Stage 1: SFT) and further improves that reasoning via reward-guided reinforcement learning against a verifiable-answer signal (Stage 2: RL).','{\"stage1_sft\": {\"epochs\": 3, \"data_size\": \"20K SFT examples (question, complex CoT, formal response)\", \"batch_size\": 128, \"learning_rate\": 0.000005}, \"stage2_ppo\": {\"reward\": \"1 for verified-correct final answer, 0.1 for incorrect, 0 for missing reasoning structure\", \"data_size\": \"20K problems reserved for RL\", \"batch_size\": 128, \"clip_range\": 0.2, \"ppo_epochs\": 3, \"learning_rate\": 0.0000005, \"discount_factor\": 1.0, \"value_coefficient\": 1.0, \"kl_coefficient_beta\": 0.03}}','[{\"role\": \"distillation\", \"dataset\": \"GBaker/MedQA-USMLE-4-options\"}, {\"role\": \"distillation\", \"dataset\": \"openlifescienceai/medmcqa\"}, {\"role\": \"distillation\", \"dataset\": \"FreedomIntelligence/medical-o1-verifiable-problem\"}, {\"role\": \"finetuning\", \"dataset\": \"FreedomIntelligence/medical-o1-reasoning-SFT\"}, {\"role\": \"preference\", \"dataset\": \"FreedomIntelligence/medical-o1-verifiable-problem\"}]','2024-12-25','{\"notes\": \"Per the paper, GPT-4o is used both as the generator that synthesizes initial CoT/answers and iteratively applies search strategies (Backtracking, Exploring New Paths, Verification, Correction) to build \'complex CoT\' reasoning trajectories, and as the verifier that gives binary True/False feedback comparing a candidate answer against the ground-truth answer (measured verifier accuracy: 96.5% in Stage 1, 94.5% in Stage 2, on 200 manually annotated samples). Three small open models (Gemma2-9B, Llama-3.1-8B, Qwen2.5-7B) were used earlier in the pipeline purely to filter out multiple-choice questions that were \'too easy\' (all three answered correctly), not as generator/verifier for the released training data.\", \"evidence\": [\"https://arxiv.org/abs/2412.18925\", \"https://huggingface.co/FreedomIntelligence/HuatuoGPT-o1-8B\"]}');
/*!40000 ALTER TABLE `transformation` ENABLE KEYS */;
UNLOCK TABLES;

