/*!50001 DROP VIEW IF EXISTS `v_model_aibom`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_0900_ai_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_model_aibom` AS select `mi`.`model_id` AS `model_id`,`mi`.`family_key` AS `family_key`,`mi`.`family_name` AS `family_name`,`mi`.`model_role` AS `model_role`,json_object('identity',`m`.`identity`,'architecture',`m`.`architecture`,'tokenizer',`m`.`tokenizer`,'modality',`m`.`modality`,'intended_use',`m`.`intended_use`,'capabilities',`m`.`capabilities`,'limitations',`m`.`limitations`,'provenance',`m`.`provenance`,'extensions',`m`.`extensions`,'catalog',json_object('model_url',`mi`.`model_url`,'revision',`mi`.`model_version`,'primary_purpose',`mi`.`primary_purpose`)) AS `model`,(select json_object('subject',`p`.`subject`,'origin',`p`.`origin`,'provider',`p`.`provider`,'parent',`p`.`parent`,'relation',`p`.`relation`,'evidence',`p`.`evidence`,'extensions',`p`.`extensions`,'evidence_uris',(select json_arrayagg(`r`.`uri`) from `reference` `r` where `r`.`id` member of (`p`.`evidence`))) from `provenance` `p` where (`p`.`id` = `m`.`provenance`)) AS `provenance`,(select json_object('input',`t`.`input`,'output',`t`.`output`,'method',`t`.`method`,'objective',`t`.`objective`,'hyperparameters',`t`.`hyperparameters`,'datasets',`t`.`datasets`,'timestamp',`t`.`timestamp`,'extensions',`t`.`extensions`) from `transformation` `t` where (`t`.`output` = `mi`.`model_id`)) AS `transformation`,(select json_arrayagg(json_object('identity',`d`.`identity`,'version',`d`.`version`,'role',`d`.`role`,'processing',`d`.`processing`,'license',`d`.`license`,'extensions',`d`.`extensions`,'parent',`dp`.`parent`,'relation',`dp`.`relation`,'disclosure_status',json_unquote(json_extract(`dp`.`extensions`,'$.disclosure_status')))) from (`dataset` `d` left join `provenance` `dp` on((`dp`.`id` = `d`.`provenance`))) where (`d`.`identity` member of ((select json_extract(`t`.`datasets`,'$[*].dataset') from `transformation` `t` where (`t`.`output` = `mi`.`model_id`))) or `d`.`identity` in (select `e`.`dataset` from `evaluation` `e` where (`e`.`model` = `mi`.`model_id`)))) AS `datasets`,(select json_arrayagg(json_object('dataset',`e`.`dataset`,'configuration',`e`.`configuration`,'metric',`e`.`metric`,'score',`e`.`score`,'timestamp',`e`.`timestamp`,'extensions',`e`.`extensions`)) from `evaluation` `e` where (`e`.`model` = `mi`.`model_id`)) AS `evaluation`,(select json_object('safety_risk',`s`.`safety_risk`,'ethical_considerations',`s`.`ethical_considerations`,'prohibited_use',`s`.`prohibited_use`,'mitigation',`s`.`mitigation`,'extensions',`s`.`extensions`) from `safety_ethics` `s` where (`s`.`subject` = `mi`.`model_id`)) AS `safety_ethics`,(select json_arrayagg(json_object('subject',`l`.`subject`,'license',`l`.`license`,'usage_policy',`l`.`usage_policy`,'restrictions',`l`.`restrictions`,'extensions',`l`.`extensions`)) from `license_policy` `l` where (`l`.`subject` = concat('model:',`mi`.`model_id`))) AS `license_policy`,(select json_arrayagg(json_object('id',`r`.`id`,'type',`r`.`type`,'uri',`r`.`uri`,'revision',`r`.`revision`,'retrieved_at',`r`.`retrieved_at`,'hash',`r`.`hash`,'extensions',`r`.`extensions`)) from `reference` `r` where (`r`.`id` member of (json_extract(`m`.`extensions`,'$.evidence')) or `r`.`id` member of ((select `p`.`evidence` from `provenance` `p` where (`p`.`id` = `m`.`provenance`))) or `r`.`uri` in (select json_unquote(json_extract(`e`.`extensions`,'$.reference')) from `evaluation` `e` where (`e`.`model` = `mi`.`model_id`)) or `r`.`uri` in (select json_unquote(`j`.`uri`) from (`transformation` `t` join json_table(`t`.`extensions`, '$.evidence[*]' columns (`uri` varchar(1000) character set utf8mb4 path '$')) `j`) where (`t`.`output` = `mi`.`model_id`)))) AS `reference` from (`model_info` `mi` left join `model` `m` on((`m`.`identity` = `mi`.`model_id`))) */;
/*!50001 SET character_set_client      = @saved_cs_client */;
